window.SDT_LESSONS=window.SDT_LESSONS||{};window.SDT_LESSONS["U8"]={"deck":"U8","slides":[{"p":1,"title":"08 미스 반 데어 로에(Ludwig Mies van der Rohe) (표지)","terms":["Ludwig Mies van der Rohe","Adolf Loos","Less is more"],"pass1":[{"kind":"say","lines":["8단원 표지예요. 연두색 띠에 '08 미스 반 데어 로에' 라고만 쓰여 있어요.","주인공은 **미스 반 데어 로에(Ludwig Mies van der Rohe)** 한 사람이에요.","주문을 떠올려요. 기계 시대에 건축은 어떻게 생겨야 하나? 싫어 → 새 장식 → 정리 → 없애.","3단원 **아돌프 로스(Adolf Loos)** 가 '없애' 를 외쳤다면, 미스는 덜어 낸 자리를 재료와 비례로 채워요."]}],"pass2":[{"kind":"points","head":"8단원에서 만날 차례","items":["1) 미스와 **적을수록 많다(Less is more)** (p.2-3)","2) **브릭 빌라(brick villa)** 계획안과 크레펠트의 두 주택 (p.4-7)","3) **바르셀로나 박람회 독일관(Barcelona Pavilion)** (p.8-12)","4) **투겐다트 주택(Tugendhat Villa)** (p.13-19)","5) 전후 모더니즘, 판스워스 하우스에서 신 국립미술관까지 (p.20-31)"]},{"kind":"points","head":"이 단원을 꿰는 한 줄","items":["**적을수록 많다(Less is more)**. 벽은 떼어 세우고, 지붕은 기둥이 들고, 장식 대신 재료의 무늬예요.","작품마다 '누가, 언제, 어디에, 무슨 재료로' 를 짝지어 외워요."]},{"kind":"look","walked":1}],"pass3":[],"walk":{"head":null,"parts":[{"b":[0.03,0.31,0.94,0.11],"c":[0.0,0.2605,1,0.2089],"r":6.3826,"img":"img/U8/walk/p001_22_01.jpg","say":"제목: 08 미스 반 데어 로에(Ludwig Mies van der Rohe). 8단원 한 사람의 이름이 곧 단원 이름이에요."}]}},{"p":2,"title":"Mies van der Rohe(1886-1969)","terms":["Ludwig Mies van der Rohe","Walter Gropius","Functionalism","Weissenhof Siedlung","지붕테라스","Barcelona Pavilion","초록색 대리석","염색된 유리 스크린","벽과 수평 슬래브의 분리","슬래브","Tugendhat Villa","마노","크롬 도금","Flat Roof","Macassar ebony"],"pass1":[{"kind":"say","lines":["**미스 반 데어 로에(Ludwig Mies van der Rohe)** 를 소개하는 쪽이에요.","**발터 그로피우스(Walter Gropius)** 와 함께 독일의 대표적 **기능주의(Functionalism)** 건축가예요.","대표작 세 개를 미리 보여 줘요. 바이센호프, 바르셀로나, 투겐다트예요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**기능주의(Functionalism)**: 건물의 사용과 기능을 형태가 그대로 드러내는 건축이에요.","**지붕테라스**: 지붕 위를 평평하게 만들어 마당처럼 쓰는 공간이에요.","**슬래브**: 지붕이나 바닥을 이루는 넓고 평평한 판이에요.","**평지붕(Flat Roof)**: 평평한 지붕이에요."]},{"kind":"points","head":"빠뜨리면 안 되는 사실","items":["**미스 반 데어 로에(Ludwig Mies van der Rohe)** 는 1886-1969년 사람이에요.","1927년 슈투트가르트의 **바이센호프 주거단지(Weissenhof Siedlung)**: **지붕테라스**를 둔 단순하고 비례적인 4층 건물로 이루어진 아파트.","1929년 **바르셀로나 박람회 독일관(Barcelona Pavilion)**: **초록색 대리석**으로 표면을 씌운 벽, 회색의 **염색된 유리 스크린**, **벽과 수평 슬래브의 분리**.","1930년 체코 브르노의 **투겐다트 주택(Tugendhat Villa)**: **마노**, 대리석, 옅은 유리색, **크롬 도금**한 철재 등 풍부한 재료.","투겐다트 주택은 작고 비대칭적인 단층의 **평지붕(Flat Roof)** 건물이라고 적혀 있어요."]},{"kind":"bg","src":"5단원 바이센호프 주거단지","lines":["**바이센호프 주거단지(Weissenhof Siedlung)** 는 5단원에서 만난 슈투트가르트의 주택 단지예요.","이 쪽은 그 단지 안 미스의 건물을 '4층 건물로 이루어진 아파트' 로 짚어 줘요.","슬라이드 위 파란 손글씨는 누가 쓴 필기인지 알 수 없어요. 이 레슨은 인쇄된 글만 따라가요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**바르셀로나 박람회 독일관(Barcelona Pavilion)** 의 세 특징이 아닌 것은 무엇일까요?","choices":["**초록색 대리석**으로 표면을 씌운 벽","회색의 **염색된 유리 스크린**","**벽과 수평 슬래브의 분리**","**마카사르 에보니(Macassar ebony)** 로 된 곡선의 스크린"],"a":3,"why":"마카사르 에보니 곡선 스크린은 투겐다트 주택(16쪽) 이야기예요."},{"kind":"check","q":"**바이센호프 주거단지(Weissenhof Siedlung)** 에서 미스의 아파트 설명으로 옳은 것은 무엇일까요?","choices":["**지붕테라스**를 둔 단순하고 비례적인 4층 건물","곡면 벽의 2층 건물","벽돌로 지은 단층 주택"],"a":0,"why":"지붕테라스를 둔 단순하고 비례적인 4층 건물로 이루어진 아파트예요. 숫자 4가 자주 나와요."},{"kind":"check","q":"세 작품을 연도 순서로 바르게 늘어놓은 것은 무엇일까요?","choices":["바이센호프(1927) → 바르셀로나(1929) → 투겐다트(1930)","바르셀로나(1929) → 바이센호프(1927) → 투겐다트(1930)","투겐다트(1930) → 바이센호프(1927) → 바르셀로나(1929)"],"a":0,"why":"1927, 1929, 1930 순서예요. 슬라이드도 이 순서로 적었어요."},{"kind":"english","head":"논술 답안: 미스 반 데어 로에 소개","en":"미스 반 데어 로에(1886-1969)는 발터 그로피우스와 함께 독일의 대표적 기능주의 건축가로, 바이센호프 주거단지(1927), 바르셀로나 박람회 독일관(1929), 투겐다트 주택(1930)을 설계하였다.","ko":"누구(생몰년), 짝꿍(그로피우스), 성격(기능주의), 대표작 세 개 순서예요.","tip":"'27 바이센호프, 29 바르셀로나, 30 투겐다트' 를 한 호흡으로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.05,0.065,0.46,0.05],"c":[0.027,0.035,0.506,0.11],"r":6.1333,"img":"img/U8/walk/p002_23_01.jpg","say":"제목: Mies van der Rohe(1886-1969). 생몰년을 함께 외워요."},{"b":[0.07,0.16,0.6,0.045],"c":[0.04,0.1158,0.66,0.1333],"r":6.6017,"img":"img/U8/walk/p002_23_02.jpg","say":"첫 줄: Walter Gropius와 함께 독일의 대표적 기능주의 건축가."},{"b":[0.07,0.28,0.7,0.11],"c":[0.035,0.2572,0.77,0.1556],"r":6.5981,"img":"img/U8/walk/p002_23_03.jpg","say":"슈투트가르트의 바이센호프 주거단지(1927년), 지붕테라스를 둔 4층 건물의 아파트예요."},{"b":[0.07,0.46,0.42,0.23],"c":[0.049,0.444,0.462,0.262],"r":2.3511,"img":"img/U8/walk/p002_23_04.jpg","say":"바르셀로나 박람회 독일관(1929년)과 세 가지 특징이에요."},{"b":[0.07,0.76,0.7,0.17],"c":[0.035,0.744,0.77,0.202],"r":5.0825,"img":"img/U8/walk/p002_23_05.jpg","say":"투겐다트 주택(1930년), 체코 브르노. 풍부한 재료, 작고 비대칭적인 단층의 평지붕 건물."}]}},{"p":3,"title":"적을수록 많다(Less is more)","terms":["Ludwig Mies van der Rohe","Less is more","미학적 순수미","모더니즘","아방가르드적 이상","Adolf Loos","Ornament und Verbrechen"],"pass1":[{"kind":"analogy","head":"방 정리","scene":"짐을 덜어 낼수록 방이 넓고 또렷해 보여요.","map":[["덜어 낸 짐","줄인 장식과 형식"],["넓고 또렷해진 방","더 풍부해진 의미"],["정리하는 사람","**미스 반 데어 로에(Ludwig Mies van der Rohe)**"]]},{"kind":"say","lines":["미스의 말 **적을수록 많다(Less is more)** 가 8단원 전체의 열쇠예요.","오른쪽 흑백 사진은 루드비히 미스 반 데어 로에예요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**적을수록 많다(Less is more)**: 덜어낼수록 오히려 더 풍부해진다는 미스의 말이에요.","**미학적 순수미**: 모더니즘의 정수를 보여 주려고 미스가 더욱 집중한 깨끗한 아름다움이에요.","**모더니즘**: 새 과학기술과 생활방식에 맞춰 모든 예술에 나타난 새 형태예요.","**아방가르드적 이상**: 새 시대에 맞는 새 미학을 꿈꾼 앞서가는 생각이에요."]},{"kind":"points","head":"'적을수록 많다' 를 푸는 세 문장","items":["**모더니즘**의 정수를 보여줄 수 있는 **미학적 순수미**에 더욱 집중했어요.","1) 장식이 적을수록 의미는 풍부해진다.","2) 형식을 절제할수록 본질에 가까워진다.","3) 과거의 양식과 결별할수록 새로운 시대를 더 잘 맞이할 수 있다.","여기에는 근대화, 산업화 과정에서 새로운 시대에 부합하는 새로운 미학을 꿈꾸었던 **아방가르드적 이상**이 반영돼요."]},{"kind":"bg","src":"3단원 아돌프 로스와 이어 보기","lines":["3단원 **아돌프 로스(Adolf Loos)** 는 **장식과 죄악(Ornament und Verbrechen)** 으로 장식을 몰아냈어요.","미스의 '장식이 적을수록 의미는 풍부해진다' 도 같은 방향이에요.","주문의 마지막 칸 '없애' 를 이어받아, 남은 것을 아름답게 다듬은 사람이 미스예요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**적을수록 많다(Less is more)** 의 해석으로 슬라이드에 없는 것은 무엇일까요?","choices":["장식이 적을수록 의미는 풍부해진다","형식을 절제할수록 본질에 가까워진다","과거의 양식과 결별할수록 새로운 시대를 더 잘 맞이할 수 있다","재료를 많이 쓸수록 공간은 풍부해진다"],"a":3,"why":"해석은 장식, 형식, 과거의 양식 세 가지예요. 재료 이야기는 없어요."},{"kind":"check","q":"'적을수록 많다' 에 반영된 이상은 무엇일까요?","choices":["**아방가르드적 이상**","중세 길드의 이상","총체예술의 이상"],"a":0,"why":"근대화, 산업화 과정에서 새 미학을 꿈꾼 아방가르드적 이상이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**적을수록 많다(Less is more)** 는 미스의 말이에요. **아돌프 로스(Adolf Loos)** 의 글은 **장식과 죄악(Ornament und Verbrechen)** 이에요.","미스가 더욱 집중한 것은 '**미학적 순수미**' 예요. 기능이나 경제성으로 바꿔 쓰지 않아요."]},{"kind":"english","head":"논술 답안: 적을수록 많다","en":"미스 반 데어 로에는 '적을수록 많다(Less is more)'라는 말로 모더니즘의 정수를 보여줄 수 있는 미학적 순수미에 더욱 집중하였고, 여기에는 새로운 미학을 꿈꾸었던 아방가르드적 이상이 반영되어 있다.","ko":"말(Less is more), 집중한 것(미학적 순수미), 바탕(아방가르드적 이상) 세 덩어리예요.","tip":"해석 세 문장은 '장식, 형식, 과거' 세 단어로 줄여 외워요."}],"walk":{"head":null,"parts":[{"b":[0.21,0.05,0.72,0.05],"c":[0.174,0,0.792,0.16],"r":6.6,"img":"img/U8/walk/p003_23_01.jpg","say":"머리글: 루드비히 미스 반 데어 로에(Ludwig Mies van der Rohe, 1886-1969)."},{"b":[0.06,0.18,0.33,0.045],"c":[0.0435,0.1475,0.363,0.11],"r":4.4,"img":"img/U8/walk/p003_23_02.jpg","say":"기울인 글씨의 인용: 적을수록 많다.(Less is more)"},{"b":[0.05,0.275,0.48,0.11],"c":[0.026,0.259,0.528,0.142],"r":4.9577,"img":"img/U8/walk/p003_23_03.jpg","say":"모더니즘의 정수를 보여줄 수 있는 미학적 순수미에 더욱 집중."},{"b":[0.05,0.39,0.48,0.21],"c":[0.026,0.374,0.528,0.242],"r":2.9091,"img":"img/U8/walk/p003_23_04.jpg","say":"해석 세 가지: 장식, 형식, 과거의 양식."},{"b":[0.05,0.615,0.48,0.15],"c":[0.026,0.599,0.528,0.182],"r":3.8681,"img":"img/U8/walk/p003_23_05.jpg","say":"아방가르드적 이상이 반영되었다는 문장이에요."},{"b":[0.555,0.215,0.37,0.68],"c":[0.5365,0.181,0.407,0.748],"r":0.7255,"img":"img/U8/walk/p003_23_06.jpg","say":"오른쪽 흑백 사진: 미스 반 데어 로에의 모습이에요."}]}},{"p":4,"title":"책 표지 (modern architecture since 1900)","terms":["brick villa","계획안","벽체"],"pass1":[{"kind":"say","lines":["책 표지 한 장이에요. william j. r. curtis 의 modern architecture since 1900 이에요.","검은 직선들이 사방으로 엇갈려 뻗어 있어요.","다음 쪽 **브릭 빌라(brick villa)** **계획안** 평면과 모양이 닮았어요."]}],"pass2":[{"kind":"points","head":"이 그림에서 볼 것","items":["출판사 이름은 PHAIDON 이에요. 슬라이드에 설명 글은 없어요.","길고 짧은 직선, 굵고 가는 직선이 서로 어긋나 있어요.","몇몇 선은 표지 끝까지 길게 뻗어 바깥으로 이어지는 것 같아요.","5쪽 글 '다양한 길이와 두께를 갖는 직선들의 조합' 을 눈으로 먼저 보는 그림이에요.","선 하나하나를 홀로 선 **벽체**라고 생각하며 보면 다음 쪽이 쉬워요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"warn","head":"헷갈리기 쉬운 점","items":["이 쪽은 책 표지라 작품 캡션이 없어요. 작품 이름과 연도는 5쪽 캡션 '**브릭 빌라(brick villa)** **계획안**, 1923' 으로 외워요.","표지 위 파란 손글씨는 출처를 모르는 필기예요. 시험 사실로 외우지 않아요."]}],"walk":{"head":null,"parts":[{"b":[0.19,0.035,0.58,0.94],"c":[0.161,0,0.638,1],"r":0.8507,"img":"img/U8/walk/p004_21_01.jpg","say":"책 표지 전체예요. 흰 바탕에 검은 직선들이 엇갈려 있어요."},{"b":[0.565,0.355,0.12,0.19],"c":[0.525,0.339,0.2,0.222],"r":1.2012,"img":"img/U8/walk/p004_21_02.jpg","say":"글자: william j. r. curtis, modern architecture since 1900."},{"b":[0.38,0.32,0.39,0.38],"c":[0.3605,0.301,0.429,0.418],"r":1.3684,"img":"img/U8/walk/p004_21_03.jpg","say":"가운데: 길이와 두께가 다른 직선들이 어긋나며 모인 곳이에요."},{"b":[0.19,0.885,0.19,0.09],"c":[0.178,0.869,0.214,0.122],"r":2.3388,"img":"img/U8/walk/p004_21_04.jpg","say":"아래 왼쪽: 출판사 PHAIDON."}]}},{"p":5,"title":"브릭 빌라(brick villa) 계획안, 1923","terms":["brick villa","계획안","벽체","개구부","공간의 중첩","axis","Flat Roof","Mass"],"pass1":[{"kind":"analogy","head":"도미노 패 세우기","scene":"책상 위에 도미노 패를 이리저리 세워 두면, 칸을 막지 않아 그 사이로 공간이 흘러요.","map":[["세워 둔 도미노 패","독립해서 서 있는 **벽체**"],["패와 패 사이 틈","열린 **개구부**"],["겹쳐 흐르는 공간","**공간의 중첩**"]]},{"kind":"say","lines":["이것이 1923년 **브릭 빌라(brick villa)** **계획안**이에요.","아직 지은 건물이 아니라 종이 위의 설계예요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**계획안**: 아직 지은 건물이 아니라 도면과 그림으로 낸 설계 제안이에요.","**벽체**: 건물의 벽이에요. 여기서는 방을 가두는 상자가 아니라 홀로 선 판이에요.","**개구부**: 벽과 벽 사이에 생긴 열린 부분이에요.","**공간의 중첩**: 엇갈린 벽 사이로 방과 방이 겹치듯 이어지는 것이에요.","**일정한 축(axis)**: 건물을 대칭으로 줄 세우는 기준선이에요.","**매스(Mass)**: 건물이 이루는 큰 덩어리예요."]},{"kind":"points","head":"빠뜨리면 안 되는 사실","items":["**브릭 빌라(brick villa)** 는 미스의 공간과 건축에 대한 이상을 읽을 수 있는 **계획안**이에요. 1923년이에요.","평면은 다양한 길이와 두께를 갖는 직선들의 조합으로 구성돼요.","직선들은 외곽으로 무한히 연장되고, 동시에 내부로는 깊숙이 파고들어 경관을 끌어들여요.","**벽체**는 독립해서 서 있는 건축요소로 변형됐어요.","**벽체**들이 서로 어긋나며 내부의 열린 **개구부**를 만들고, 이로써 **공간의 중첩**이 생겨요.","1, 2층의 층고를 갖는 **평지붕(Flat Roof)** 의 **매스(Mass)** 이고, **일정한 축(axis)** 없이 자유롭게 배치됐어요."]},{"kind":"points","head":"그림에서 볼 것","items":["위 그림은 투시도예요. 낮고 납작한 덩어리들이 옆으로 길게 이어져요.","아래 그림은 평면이에요. 직선 벽들이 서로 닿지 않고 어긋나 있어요.","몇몇 벽은 그림 가장자리까지 길게 뻗어 나가요. 4쪽 책 표지와 닮았어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**브릭 빌라(brick villa)** **계획안**의 연도는 언제일까요?","choices":["1922","1923","1927"],"a":1,"why":"1923년이에요. 1927년은 랑에 주택과 바이센호프 아파트의 해예요."},{"kind":"check","q":"**브릭 빌라(brick villa)** 의 설명으로 틀린 것은 무엇일까요?","choices":["**벽체**는 독립해서 서 있는 건축요소로 변형","벽체들이 어긋나며 내부 공간들이 중첩","**일정한 축(axis)** 을 따라 대칭으로 배치","1, 2층의 층고를 갖는 평지붕의 매스"],"a":2,"why":"일정한 축 없이 자유롭게 배치했어요. '축을 따라 대칭' 은 반대 말이에요."},{"kind":"check","q":"벽체들이 서로 어긋나며 열린 개구부를 만들 때 내부 공간에 생기는 일은 무엇일까요?","choices":["**공간의 중첩**","공간의 단절","공간의 대칭"],"a":0,"why":"어긋난 벽 사이로 공간들이 겹쳐요. 공간의 중첩이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["슬라이드 글은 '무한이 연장됨' 이라고 적었지만 바른 말은 '무한히' 예요.","**브릭 빌라(brick villa)** 는 지은 건물이 아니라 **계획안**이에요. 사진이 아니라 투시도와 평면이 실렸어요."]},{"kind":"english","head":"논술 답안: 브릭 빌라 계획안","en":"브릭 빌라 계획안(1923)은 다양한 길이와 두께의 직선들이 외곽으로 무한히 연장되고 내부로 경관을 끌어들이며, 독립한 벽체들이 어긋나 공간을 중첩시키고 일정한 축 없이 자유롭게 배치되었다.","ko":"직선, 독립한 벽체, 공간의 중첩, 축 없음 네 가지를 넣어요.","tip":"'이삼(23), 벽이 삼삼오오 흩어져 사방으로' 로 연도를 외워요."}],"walk":{"head":null,"parts":[{"b":[0.07,0.03,0.2,0.04],"c":[0.058,0,0.224,0.11],"r":2.7152,"img":"img/U8/walk/p005_23_01.jpg","say":"제목: 브릭 빌라(brick villa)."},{"b":[0.05,0.125,0.58,0.045],"c":[0.021,0.0831,0.638,0.1289],"r":6.5994,"img":"img/U8/walk/p005_23_02.jpg","say":"공간과 건축에 대한 이상을 읽을 수 있는 계획안."},{"b":[0.05,0.18,0.92,0.1],"c":[0,0.1278,1,0.2045],"r":6.52,"img":"img/U8/walk/p005_23_03.jpg","say":"직선들이 외곽으로 연장되고 내부로 파고들어 경관을 끌어들인다는 문장이에요."},{"b":[0.05,0.295,0.92,0.11],"c":[0,0.2478,1,0.2045],"r":6.52,"img":"img/U8/walk/p005_23_04.jpg","say":"벽체는 독립한 건축요소, 어긋난 벽체가 개구부를 만들고 공간이 중첩돼요."},{"b":[0.425,0.47,0.505,0.5],"c":[0.3997,0.445,0.5555,0.55],"r":1.3467,"img":"img/U8/walk/p005_23_05.jpg","say":"오른쪽 아래 그림: 위는 투시도, 아래는 직선 벽들이 엇갈린 평면이에요."},{"b":[0.07,0.94,0.33,0.035],"c":[0.0535,0.89,0.363,0.11],"r":4.4,"img":"img/U8/walk/p005_23_06.jpg","say":"캡션: 미스 반 데어 로에, 브릭 빌라 계획안, 1923."}]}},{"p":6,"title":"에스터 주택(Haus Ester), 독일 크레펠트, 1928","terms":["Haus Ester","Flat Roof","brick villa"],"pass1":[{"kind":"say","lines":["사진 두 장 모두 **에스터 주택(Haus Ester)** 이에요. 독일 크레펠트, 1928년이에요.","붉은 벽돌 벽에 가로로 긴 창이 나 있어요.","앞의 **브릭 빌라(brick villa)** 는 종이 위 계획이었고, 이건 실제로 지은 벽돌집이에요."]}],"pass2":[{"kind":"points","head":"이 사진에서 볼 것","items":["캡션: 미스 반 데어 로에, **에스터 주택(Haus Ester)**, 독일 크레펠트, 1928.","왼쪽 사진: 2층 벽돌 건물 옆으로 얇은 흰 차양 지붕이 앞으로 나와 있고, 그 아래는 유리벽이에요.","오른쪽 사진: 넓은 잔디 너머로 본 긴 벽돌집이에요. 지붕은 **평지붕(Flat Roof)** 이고 창이 가로로 줄지어 있어요.","잔디 위에 녹슨 색 네모 기둥 모양 조형물 두 개가 서 있어요. 이름은 슬라이드에 없어요.","이 쪽에는 설명 글이 없어요. 캡션과 사진만 있어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**에스터 주택(Haus Ester)** 의 도시와 연도로 옳은 것은 무엇일까요?","choices":["독일 크레펠트, 1928","체코 브르노, 1930","독일 슈투트가르트, 1927"],"a":0,"why":"독일 크레펠트, 1928년이에요. 브르노는 투겐다트 주택, 슈투트가르트는 바이센호프예요."}],"walk":{"head":null,"parts":[{"b":[0.01,0.255,0.485,0.485],"c":[0,0.2308,0.5335,0.5335],"r":1.3333,"img":"img/U8/walk/p006_21_01.jpg","say":"왼쪽 사진: 벽돌 벽, 가로로 긴 창, 얇게 내민 흰 차양 아래 유리벽이에요."},{"b":[0.505,0.255,0.485,0.485],"c":[0.4665,0.2308,0.5335,0.5335],"r":1.3333,"img":"img/U8/walk/p006_21_02.jpg","say":"오른쪽 사진: 잔디밭에서 본 긴 벽돌집이에요. 평평한 지붕이에요."},{"b":[0.325,0.745,0.5,0.035],"c":[0.3,0.7069,0.55,0.1111],"r":6.6007,"img":"img/U8/walk/p006_21_03.jpg","say":"캡션: 미스 반 데어 로에, 에스터 주택(Haus Ester), 독일 크레펠트, 1928."}]}},{"p":7,"title":"랑에 주택(Haus Lange, 1927)과 에스터 주택(Haus Ester, 1928), 독일 크레펠트","terms":["Haus Lange","Haus Ester","brick villa","Weissenhof Siedlung","Flat Roof"],"pass1":[{"kind":"say","lines":["**랑에 주택(Haus Lange)** 과 **에스터 주택(Haus Ester)** 을 함께 보여 주는 쪽이에요.","둘 다 독일 크레펠트의 벽돌집이에요. 랑에 1927, 에스터 1928, 랑에가 1년 먼저예요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**랑에 주택(Haus Lange)**: 독일 크레펠트에 있는 미스의 벽돌 주택(1927)이에요.","**에스터 주택(Haus Ester)**: 같은 크레펠트의 미스의 벽돌 주택(1928)이에요.","Haus 는 독일어로 '집' 이라는 뜻이에요."]},{"kind":"compare","head":"크레펠트의 두 벽돌집","cols":["","랑에 주택(Haus Lange)","에스터 주택(Haus Ester)"],"rows":[["연도","1927","1928"],["도시","독일 크레펠트","독일 크레펠트"],["사진에서 보이는 것","붉은 벽돌, 가로로 긴 창","붉은 벽돌, 가로로 긴 창"]]},{"kind":"points","head":"사진과 도면에서 볼 것","items":["위 사진 두 장: 붉은 벽돌 벽, 가로로 긴 창, 얇게 내민 평평한 차양이 보여요. **평지붕(Flat Roof)** 이에요.","아래 도면 두 장은 평면도예요. 굵은 검은 선이 벽이고 방들이 여러 칸으로 나뉘어요.","5쪽 **브릭 빌라(brick villa)** 평면보다 벽이 방을 더 많이 둘러싸고 있어요.","캡션은 두 집을 함께 적었어요. 어느 사진이 어느 집인지는 따로 적혀 있지 않아요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**랑에 주택(Haus Lange)** 과 **에스터 주택(Haus Ester)** 의 연도 짝으로 옳은 것은 무엇일까요?","choices":["랑에 1928, 에스터 1927","랑에 1927, 에스터 1928","둘 다 1929"],"a":1,"why":"랑에 1927, 에스터 1928이에요. 랑에가 1년 먼저예요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["두 집 모두 독일 크레펠트예요. 투겐다트 주택의 체코 브르노와 섞지 않아요.","1927년은 **바이센호프 주거단지(Weissenhof Siedlung)** 의 4층 아파트와 같은 해예요.","가나다 순서(랑 → 에)와 연도 순서(27 → 28)가 같아요. 그렇게 외우면 안 바뀌어요."]}],"walk":{"head":null,"parts":[{"b":[0.495,0.04,0.4,0.04],"c":[0.475,0.005,0.44,0.11],"r":5.3333,"img":"img/U8/walk/p007_23_01.jpg","say":"제목: 랑에 주택(Haus Lange, 1927)과 에스터 주택."},{"b":[0.01,0.11,0.44,0.44],"c":[0,0.088,0.484,0.484],"r":1.3333,"img":"img/U8/walk/p007_23_02.jpg","say":"왼쪽 사진: 벽돌 벽, 가로로 긴 창, 길게 내민 흰 차양이에요."},{"b":[0.455,0.115,0.43,0.43],"c":[0.4335,0.0935,0.473,0.473],"r":1.3333,"img":"img/U8/walk/p007_23_03.jpg","say":"오른쪽 사진: 네모난 벽돌 덩어리와 현관 위 얇은 차양이에요."},{"b":[0.07,0.555,0.75,0.035],"c":[0.0325,0.4892,0.825,0.1667],"r":6.5987,"img":"img/U8/walk/p007_23_04.jpg","say":"캡션: 랑에 주택(Haus Lange, 1927)과 에스터 주택(Haus Ester, 1928), 독일 크레펠트."},{"b":[0.14,0.645,0.38,0.34],"c":[0.121,0.626,0.418,0.374],"r":1.4902,"img":"img/U8/walk/p007_23_05.jpg","say":"왼쪽 아래 평면도예요. 굵은 선이 벽이에요."},{"b":[0.555,0.645,0.36,0.31],"c":[0.537,0.629,0.396,0.342],"r":1.5439,"img":"img/U8/walk/p007_23_06.jpg","say":"오른쪽 아래 평면도예요. 방들이 칸으로 나뉘어 있어요."}]}},{"p":8,"title":"바르셀로나 박람회 독일관(1929년)","terms":["Barcelona Pavilion","Weimar","openness, liberality, modernity, internationalism","clarity, simplicity, honesty","초록색 대리석","염색된 유리 스크린","벽과 수평 슬래브의 분리","슬래브","수공간","스틸 기둥"],"pass1":[{"kind":"analogy","head":"쟁반과 카드","scene":"쟁반을 가는 막대 몇 개로 받쳐 들고, 그 아래에 카드를 여기저기 세워 두었다고 생각해요.","map":[["쟁반","평평한 지붕판(**슬래브**)"],["가는 막대","**스틸 기둥**"],["여기저기 세운 카드","지붕을 받치지 않는 벽"]]},{"kind":"say","lines":["1929년 **바르셀로나 박람회 독일관(Barcelona Pavilion)** 이에요.","카드가 쟁반을 받치지 않아요. 이것이 **벽과 수평 슬래브의 분리**예요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**바이마르 공화국(Weimar)**: 이 독일관이 이념을 홍보하려 한 당시 독일 공화국이에요.","**명료성, 단순성, 솔직성(clarity, simplicity, honesty)**: 이 독일관 디자인의 원칙 세 가지예요.","**슬래브**: 지붕이나 바닥을 이루는 넓고 평평한 판이에요.","**수공간**: 물을 담아 둔 연못 같은 공간이에요. 슬라이드는 수(水)공간이라고 적었어요."]},{"kind":"points","head":"빠뜨리면 안 되는 사실","items":["**바이마르 공화국(Weimar)** 의 이상인 '**개방성, 자유, 근대성, 국제주의(openness, liberality, modernity, internationalism)**' 를 홍보하려 했어요.","그 이념을 국제적으로 홍보하기 위한 상징적 건물로 디자인했어요.","원칙은 '**명료성, 단순성, 솔직성(clarity, simplicity, honesty)**' 이에요.","보이는 모습 셋: **초록색 대리석**으로 표면을 씌운 벽, 회색의 **염색된 유리 스크린**, **벽과 수평 슬래브의 분리**.","크롬, 대리석, 유리, **수공간** 등이 조화를 이루는 시각적 즐거움이 있어요.","차가운 감성적 디자인이 모던함을 상징적으로 표현해요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**바르셀로나 박람회 독일관(Barcelona Pavilion)** 이 홍보하려 한 **바이마르 공화국(Weimar)** 의 이상이 아닌 것은 무엇일까요?","choices":["개방성","자유","국제주의","전통성"],"a":3,"why":"이상 넷은 개방성, 자유, 근대성, 국제주의예요."},{"kind":"check","q":"독일관 디자인 원칙 세 가지로 옳은 것은 무엇일까요?","choices":["**명료성, 단순성, 솔직성(clarity, simplicity, honesty)**","개방성, 자유, 근대성","합리성, 경제성, 기능성"],"a":0,"why":"명료성, 단순성, 솔직성이에요. 개방성, 자유, 근대성은 바이마르 공화국의 이상 쪽이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["이상은 네 개(**개방성, 자유, 근대성, 국제주의**), 원칙은 세 개(**명료성, 단순성, 솔직성**)예요. 두 묶음을 섞지 않아요.","벽의 표면은 **초록색 대리석**, 유리 스크린은 회색이에요. 색을 바꾼 O/X 를 조심해요.","글 아래 파란 손글씨는 출처를 모르는 필기예요. 시험 사실로 외우지 않아요."]},{"kind":"english","head":"논술 답안: 바르셀로나 독일관의 이념","en":"바르셀로나 박람회 독일관(1929)은 바이마르 공화국의 이상인 개방성, 자유, 근대성, 국제주의를 국제적으로 홍보하기 위한 상징적 건물로, 명료성, 단순성, 솔직성을 원칙으로 하였다.","ko":"목적(바이마르 이상 홍보)과 원칙(명료성, 단순성, 솔직성)을 한 문장에 넣어요.","tip":"'이구동성(29)으로 명료성, 단순성, 솔직성' 으로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.08,0.07,0.32,0.04],"c":[0.064,0.035,0.352,0.11],"r":4.2667,"img":"img/U8/walk/p008_22_01.jpg","say":"제목: 바르셀로나 박람회 독일관(1929년)."},{"b":[0.1,0.18,0.85,0.155],"c":[0.0575,0.163,0.935,0.1889],"r":6.5996,"img":"img/U8/walk/p008_22_02.jpg","say":"바이마르 공화국의 이상 네 가지, 국제적으로 홍보하기 위한 상징적 건물."},{"b":[0.1,0.35,0.55,0.05],"c":[0.0725,0.3139,0.605,0.1222],"r":6.6012,"img":"img/U8/walk/p008_22_03.jpg","say":"원칙: 명료성, 단순성, 솔직성(clarity, simplicity, honesty)."},{"b":[0.15,0.41,0.37,0.17],"c":[0.1315,0.394,0.407,0.202],"r":2.6865,"img":"img/U8/walk/p008_22_04.jpg","say":"세 가지 모습: 초록색 대리석 벽, 회색 염색 유리 스크린, 벽과 수평 슬래브의 분리."},{"b":[0.1,0.59,0.85,0.1],"c":[0.0575,0.5455,0.935,0.1889],"r":6.5996,"img":"img/U8/walk/p008_22_05.jpg","say":"크롬, 대리석, 유리, 수(水)공간의 시각적 즐거움, 차가운 감성적 디자인."}]}},{"p":9,"title":"바르셀로나 박람회 독일관의 평면과 트레버틴 벽체","terms":["Barcelona Pavilion","칸막이 같은 벽","travertine","벽체","크롬 도금"],"pass1":[{"kind":"say","lines":["독일관의 평면도와 실내 사진이에요.","막힌 벽 대신 유리와 대리석 판을 **칸막이 같은 벽**으로 세웠어요.","앞 쪽 비유의 '여기저기 세운 카드' 가 바로 이 벽들이에요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**칸막이 같은 벽**: 막힌 벽 대신 유리와 대리석 판을 칸막이처럼 세운 벽이에요.","**트레버틴(travertine)**: 독일관의 **벽체**에 쓰인 돌 재료예요."]},{"kind":"points","head":"빠뜨리면 안 되는 사실","items":["막혀진 벽 없이 유리와 대리석으로 된 **칸막이 같은 벽**들이 불규칙하게 배열됐어요.","하지만 직선의 추상적인 패턴으로 배열됐어요.","화려한 소재들과 평면들의 추상적인 구성, 몇 개의 모던한 조각 작품들이 있어요.","어떤 특정한 기능을 위해 필요한 경우 더욱 열려 있는 공간을 형성하도록 자유롭게 계획했어요.","두 개의 양단 **트레버틴(travertine)** **벽체**가 공간을 에워싸며 내부공간을 수용해요.","캡션: 스페인 바르셀로나, 1929. 지금 건물은 1986년에 복원한 것이에요."]},{"kind":"points","head":"평면과 사진에서 볼 것","items":["왼쪽 평면: 긴 직선 벽들이 서로 닿지 않고 따로 서 있어요. 왼쪽 아래 격자 칸은 넓은 물 면이에요.","오른쪽 사진: 물결 무늬의 붉은 대리석 판이 홀로 서 있어요.","사진 오른쪽에 반짝이는 가는 기둥 하나가 천장을 받쳐요. 벽 앞에는 낮은 의자들이 있어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"독일관에서 공간을 에워싸는 두 개의 양단 벽체의 재료는 무엇일까요?","choices":["**트레버틴(travertine)**","**오닉스(onyx)**","**마노**"],"a":0,"why":"트레버틴이에요. 오닉스와 마노는 투겐다트 주택 재료예요."},{"kind":"check","q":"독일관 벽의 배열 설명으로 옳은 것은 무엇일까요?","choices":["대칭으로 반복된 막힌 벽","불규칙하지만 직선의 추상적인 패턴","곡선으로 휘어진 벽"],"a":1,"why":"칸막이 같은 벽들이 불규칙하게, 하지만 직선의 추상적인 패턴으로 놓였어요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["캡션은 '미스 반 데에 로에' 로 적혔어요. 바른 표기는 미스 반 데어 로에예요.","'1986 복원' 은 다시 지은 해예요. 박람회 해는 1929년이에요.","평면과 사진 위 파란 손글씨는 출처를 모르는 필기예요. 시험 사실로 외우지 않아요."]}],"walk":{"head":null,"parts":[{"b":[0.05,0.075,0.88,0.11],"c":[0.006,0.0322,0.968,0.1956],"r":6.5985,"img":"img/U8/walk/p009_23_01.jpg","say":"칸막이 같은 벽들의 불규칙한 배열, 하지만 직선의 추상적인 패턴."},{"b":[0.05,0.195,0.75,0.045],"c":[0.0125,0.1342,0.825,0.1667],"r":6.5987,"img":"img/U8/walk/p009_23_02.jpg","say":"화려한 소재들과 평면들의 추상적인 구성, 몇 개의 모던한 조각 작품들."},{"b":[0.05,0.315,0.8,0.05],"c":[0.01,0.2511,0.88,0.1778],"r":6.5992,"img":"img/U8/walk/p009_23_03.jpg","say":"두 개의 양단 트레버틴(travertine) 벽체가 공간을 에워싸요."},{"b":[0.03,0.54,0.37,0.22],"c":[0.0115,0.524,0.407,0.252],"r":2.1534,"img":"img/U8/walk/p009_23_04.jpg","say":"왼쪽 평면도: 따로 선 직선 벽들이 보여요."},{"b":[0.43,0.395,0.535,0.47],"c":[0.4032,0.3715,0.5885,0.517],"r":1.5177,"img":"img/U8/walk/p009_23_05.jpg","say":"오른쪽 사진: 무늬 대리석 판 벽, 가는 기둥, 낮은 의자, 큰 유리창이에요."},{"b":[0.44,0.87,0.53,0.115],"c":[0.4135,0.853,0.583,0.147],"r":5.288,"img":"img/U8/walk/p009_23_06.jpg","say":"캡션: 바르셀로나 박람회 독일관(Barcelona Pavilion), 스페인 바르셀로나, 1929. 1986 복원."}]}},{"p":10,"title":"여덟 개의 스틸 기둥과 십자형 기둥","terms":["Barcelona Pavilion","스틸 기둥","십자형 기둥","크롬 도금","선택적인 요소","구조미","슬래브","수공간"],"pass1":[{"kind":"say","lines":["평평한 지붕을 받치는 것은 벽이 아니라 기둥 여덟 개예요.","그래서 벽은 있어도 되고 없어도 되는 **선택적인 요소** 가 됐어요.","왼쪽 검은 그림은 더하기(+) 모양 **십자형 기둥** 의 단면이에요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**스틸 기둥**: 강철로 만든 가는 기둥이에요.","**십자형 기둥**: 단면이 더하기(+) 모양인 **크롬 도금** 기둥이에요.","**크롬 도금**: 금속 표면에 크롬을 입혀 거울처럼 반짝이게 한 마감이에요.","**선택적인 요소**: 기둥이 지붕을 받치니 벽은 있어도 되고 없어도 되는 것이에요.","**구조미**: 꾸밈 대신 구조 자체에서 나오는 아름다움이에요."]},{"kind":"points","head":"빠뜨리면 안 되는 사실","items":["평평한 슬라브 지붕을 지지하는 여덟 개의 **스틸 기둥**으로 된 단순한 구조물이에요.","파빌리온 그 자체만으로도 하나의 추상적인 예술작품이에요.","강철과 콘크리트의 근대적 구조 기술의 능력을 완전히 이용해 벽들을 **선택적인 요소**로 만들었어요.","미스: '구조는 건물의 용도보다 더 중요하며, 용도는 변화할 수 있지만 구조는 그대로 남는다.'","크롬으로 도금한 **십자형 기둥**은 재료를 최소한으로 사용하면서 혁신적 재료가 줄 수 있는 **구조미**를 표현해요."]},{"kind":"points","head":"그림과 사진에서 볼 것","items":["왼쪽 그림: **십자형 기둥** 단면이에요. 숫자는 적혀 있지 않아요.","오른쪽 사진: 얇은 지붕판이 앞으로 내밀어 있고, 그 아래 유리벽이 보여요.","왼쪽은 베이지색 긴 돌 벽과 낮은 벤치, 오른쪽은 물이 담긴 **수공간**이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"독일관의 평평한 지붕을 지지하는 것은 무엇일까요?","choices":["여덟 개의 **스틸 기둥**","두 개의 트레버틴 벽","네 개의 콘크리트 기둥"],"a":0,"why":"여덟 개의 스틸 기둥이에요. 그래서 벽이 선택적인 요소가 됐어요."},{"kind":"check","q":"미스가 한 말로 옳은 것은 무엇일까요?","choices":["구조는 건물의 용도보다 더 중요하며, 용도는 변화할 수 있지만 구조는 그대로 남는다","용도는 구조보다 더 중요하며, 구조는 변화할 수 있지만 용도는 그대로 남는다","장식은 구조보다 더 중요하며, 장식만이 그대로 남는다"],"a":0,"why":"그대로 남는 것은 구조예요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["구조와 용도의 자리를 바꾼 O/X 가 함정이에요. 그대로 남는 것은 구조예요.","이 쪽은 '슬라브', 2쪽과 8쪽은 '**슬래브**' 로 적었어요. 같은 말이에요.","캡션의 '데에' 는 오타예요. 미스 반 데어 로에가 맞아요.","그림과 사진 위 파란 손글씨는 출처를 모르는 필기예요."]},{"kind":"english","head":"논술 답안: 구조와 벽","en":"바르셀로나 박람회 독일관은 평평한 슬래브 지붕을 여덟 개의 스틸 기둥이 지지하는 단순한 구조물로, 벽들을 선택적인 요소로 만들었으며, 크롬 도금한 십자형 기둥으로 구조미를 표현하였다.","ko":"기둥 수(8), 벽의 성격(선택적인 요소), 기둥 모양(십자형, 크롬) 세 가지예요.","tip":"'쟁반은 막대 여덟 개가 들고, 카드는 마음대로' 로 떠올려요."}],"walk":{"head":null,"parts":[{"b":[0.06,0.05,0.83,0.045],"c":[0.0185,0,0.913,0.1845],"r":6.598,"img":"img/U8/walk/p010_23_01.jpg","say":"평평한 슬라브 지붕을 지지하는 여덟 개의 스틸 기둥."},{"b":[0.06,0.165,0.91,0.1],"c":[0,0.1139,1,0.2022],"r":6.5941,"img":"img/U8/walk/p010_23_02.jpg","say":"근대적 구조 기술로 벽들을 선택적인 요소로 만든 건물."},{"b":[0.06,0.27,0.91,0.105],"c":[0,0.2214,1,0.2022],"r":6.5941,"img":"img/U8/walk/p010_23_03.jpg","say":"미스의 말: 구조는 용도보다 더 중요하다."},{"b":[0.06,0.385,0.91,0.1],"c":[0,0.3339,1,0.2022],"r":6.5941,"img":"img/U8/walk/p010_23_04.jpg","say":"크롬 도금한 십자형 기둥이 구조미를 표현한다는 문장이에요."},{"b":[0.055,0.58,0.3,0.33],"c":[0.04,0.5635,0.33,0.363],"r":1.2121,"img":"img/U8/walk/p010_23_05.jpg","say":"왼쪽 아래 그림: 십자형 기둥의 단면이에요."},{"b":[0.38,0.43,0.545,0.515],"c":[0.3528,0.4042,0.5995,0.5665],"r":1.411,"img":"img/U8/walk/p010_23_06.jpg","say":"오른쪽 사진: 얇게 내민 지붕, 돌 벽, 물이 담긴 수공간이에요."}]}},{"p":11,"title":"차가움 속의 시각적 조화","terms":["차가움 속의 시각적 조화","비례감","axis","수공간","brick villa","Barcelona Pavilion"],"pass1":[{"kind":"say","lines":["독일관의 느낌을 한 줄로 요약한 쪽이에요.","'**차가움 속의 시각적 조화**'. 대리석, 유리, 금속은 차갑지만 함께 놓이니 보기 좋아요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**차가움 속의 시각적 조화**: 독일관의 차갑지만 보기 좋은 조화를 요약한 말이에요.","**비례감**: 부분과 부분의 크기 관계가 잘 맞는 느낌이에요.","**일정한 축(axis)**: 대칭으로 줄 세우는 기준선이에요. 독일관은 이것을 강조하지 않아요."]},{"kind":"points","head":"빠뜨리면 안 되는 사실","items":["대칭적이거나 축을 강조하는 형식상의 엄격함과는 거리를 두어요.","오히려 자유로운 시각적 즐거움을 추구하는 조형 원칙이에요.","각기 다른 건물 요소들을 조화시키는 **비례감**과 기하학적 구성에 비중을 두었어요.","그래서 이를 총체적인 미적 대상으로 완성했어요.","합리성과 경제성으로 창조할 수 있는 무한한 공간과 장소 생성의 가능성을 제시했어요."]},{"kind":"points","head":"사진에서 볼 것","items":["왼쪽: 검은 무늬 대리석 벽 옆으로 얕은 물이 담긴 **수공간**과 밝은 돌 담이 보여요.","오른쪽: 가는 테두리의 유리벽이 줄지어 있고, 왼쪽에 결 무늬 대리석 벽이 있어요."]},{"kind":"bg","src":"5쪽 브릭 빌라와 이어 보기","lines":["5쪽 **브릭 빌라(brick villa)** 도 **일정한 축(axis)** 없이 자유롭게 배치했어요.","축을 피하는 생각이 계획안에서 **바르셀로나 박람회 독일관(Barcelona Pavilion)** 까지 이어져요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"'**차가움 속의 시각적 조화**' 의 설명으로 틀린 것은 무엇일까요?","choices":["대칭적이거나 축을 강조하는 엄격함과 거리를 둠","자유로운 시각적 즐거움을 추구","**비례감**과 기하학적 구성에 비중","대칭과 축을 엄격하게 강조"],"a":3,"why":"독일관은 대칭과 축의 엄격함에서 거리를 두었어요."},{"kind":"check","q":"독일관이 무한한 공간과 장소 생성의 가능성을 만든 바탕은 무엇일까요?","choices":["합리성과 경제성","장식과 상징성","전통과 지역성"],"a":0,"why":"합리성과 경제성으로 창조할 수 있는 무한한 공간과 장소 생성의 가능성이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["슬라이드 글 '형식상의의 엄격함' 은 '의' 가 겹친 오타예요. 형식상의 엄격함이 맞아요."]}],"walk":{"head":null,"parts":[{"b":[0.06,0.07,0.3,0.045],"c":[0.045,0.0375,0.33,0.11],"r":4.0,"img":"img/U8/walk/p011_24_01.jpg","say":"핵심 말: '차가움 속의 시각적 조화'."},{"b":[0.06,0.13,0.9,0.1],"c":[0.01,0.08,0.99,0.2],"r":6.6,"img":"img/U8/walk/p011_24_02.jpg","say":"대칭이나 축을 강조하는 엄격함과 거리, 자유로운 시각적 즐거움."},{"b":[0.06,0.245,0.9,0.1],"c":[0.01,0.195,0.99,0.2],"r":6.6,"img":"img/U8/walk/p011_24_03.jpg","say":"비례감과 기하학적 구성으로 총체적인 미적 대상으로 완성."},{"b":[0.06,0.36,0.83,0.045],"c":[0.0185,0.2903,0.913,0.1845],"r":6.598,"img":"img/U8/walk/p011_24_04.jpg","say":"합리성과 경제성으로 무한한 공간과 장소 생성의 가능성을 제시."},{"b":[0.035,0.49,0.46,0.455],"c":[0.012,0.4672,0.506,0.5005],"r":1.348,"img":"img/U8/walk/p011_24_05.jpg","say":"왼쪽 사진: 무늬 대리석 벽과 얕은 물이에요."},{"b":[0.505,0.49,0.46,0.455],"c":[0.482,0.4672,0.506,0.5005],"r":1.348,"img":"img/U8/walk/p011_24_06.jpg","say":"오른쪽 사진: 가는 테두리의 유리벽 줄과 결 무늬 대리석 벽이에요."}]}},{"p":12,"title":"공간의 자유와 투명성, 게오르그 콜베의 조각상","terms":["cantilever","유동적 공간","공간의 자유","투명성","크롬 도금","게오르그 콜베","Barcelona Pavilion"],"pass1":[{"kind":"say","lines":["가벼운 기둥, 날렵한 지붕, 흐르는 공간. 벽에 갇히지 않는 **공간의 자유** 예요.","유리, 대리석, 크롬이 서로 비치며 **투명성** 을 만들어요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**캔틸레버(cantilever)**: 한쪽 끝만 고정하고 다른 끝은 받침 없이 내민 구조예요.","**유동적 공간**: 벽에 갇히지 않고 흐르듯 이어지는 공간이에요.","**공간의 자유**: 구조와 재료에 구속되지 않는 자유로운 공간이에요.","**투명성**: 유리와 반사로 안과 밖이 비쳐 보이는 성질이에요.","**게오르그 콜베**: 독일관에 선 조각상의 작가예요."]},{"kind":"points","head":"빠뜨리면 안 되는 사실","items":["가벼운 기둥들이 떠받치는 열린 공간, **캔틸레버(cantilever)** 의 날렵한 지붕, **유동적 공간**이 있어요.","이 셋은 구조 및 재료에 구속되지 않는 **공간의 자유**를 의미해요.","채색된 유리, 거울과 같이 빛나는 대리석, **크롬 도금**의 가구 프레임이 주는 광택이 조화롭게 어울려요.","그래서 다양한 방식으로 **투명성**을 표현해 미학적 완성도를 높였어요."]},{"kind":"points","head":"사진에서 볼 것","items":["왼쪽: **게오르그 콜베**의 조각상이 물 위에 서 있고, 짙은 무늬 대리석 벽이 둘러싸요.","왼쪽 벽면에 조각상이 거울처럼 비쳐요. 대리석이 '거울과 같이 빛나는' 모습이에요.","오른쪽: 굽이치는 결 무늬 대리석 벽 앞에 반짝이는 다리의 의자들이 놓여 있어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"독일관에서 **투명성**을 표현한 것으로 슬라이드에 없는 것은 무엇일까요?","choices":["채색된 유리","거울과 같이 빛나는 대리석","크롬 도금의 가구 프레임","**마카사르 에보니(Macassar ebony)** 곡선 스크린"],"a":3,"why":"마카사르 에보니는 투겐다트 주택의 다이닝 스크린이에요."},{"kind":"check","q":"독일관에 선 조각상의 작가는 누구일까요?","choices":["**게오르그 콜베**","막스 베르크","요제프 호프만"],"a":0,"why":"슬라이드 캡션은 '게오르그 콜베의 조각상' 이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**공간의 자유**를 뜻하는 셋은 열린 공간, **캔틸레버(cantilever)** 의 날렵한 지붕, **유동적 공간**이에요.","오른쪽 사진 위 파란 손글씨는 출처를 모르는 필기예요."]},{"kind":"english","head":"논술 답안: 공간의 자유와 투명성","en":"가벼운 기둥들이 떠받치는 열린 공간, 캔틸레버의 날렵한 지붕, 유동적 공간은 공간의 자유를 의미하며, 채색된 유리, 빛나는 대리석, 크롬 도금의 가구 프레임이 다양한 방식으로 투명성을 표현하였다.","ko":"공간의 자유 셋, 투명성 재료 셋을 짝지어 넣어요.","tip":"'기둥, 지붕, 흐름은 자유 / 유리, 대리석, 크롬은 투명' 으로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.085,0.065,0.86,0.11],"c":[0.042,0.0244,0.946,0.1911],"r":6.6004,"img":"img/U8/walk/p012_23_01.jpg","say":"열린 공간, 캔틸레버의 날렵한 지붕, 유동적 공간은 공간의 자유를 의미."},{"b":[0.085,0.185,0.86,0.15],"c":[0.042,0.1644,0.946,0.1911],"r":6.6004,"img":"img/U8/walk/p012_23_02.jpg","say":"채색된 유리, 빛나는 대리석, 크롬 도금 가구 프레임으로 투명성을 표현."},{"b":[0.015,0.395,0.48,0.485],"c":[0,0.3707,0.528,0.5335],"r":1.3196,"img":"img/U8/walk/p012_23_03.jpg","say":"왼쪽 사진: 물 위의 조각상과 무늬 대리석 벽이에요."},{"b":[0.045,0.9,0.18,0.035],"c":[0.033,0.8625,0.204,0.11],"r":2.4727,"img":"img/U8/walk/p012_23_04.jpg","say":"캡션: 게오르그 콜베의 조각상."},{"b":[0.505,0.395,0.48,0.49],"c":[0.472,0.3705,0.528,0.539],"r":1.3061,"img":"img/U8/walk/p012_23_05.jpg","say":"오른쪽 사진: 결 무늬 대리석 벽 앞의 의자들이에요."}]}},{"p":13,"title":"투겐다트 주택(Tugendhat Villa)","terms":["Tugendhat Villa","마노","크롬 도금","Flat Roof","개방성과 폐쇄성의 대비","travertine","Barcelona Pavilion"],"pass1":[{"kind":"analogy","head":"원단의 결이 무늬인 옷","scene":"그림을 그려 넣지 않아도 원단의 결 자체가 멋진 옷이 있어요.","map":[["그려 넣은 무늬","덧붙인 장식"],["원단의 결","**마노**, 대리석 같은 재료의 무늬"],["결이 고운 옷","**투겐다트 주택(Tugendhat Villa)**"]]},{"kind":"say","lines":["체코 브르노의 **투겐다트 주택(Tugendhat Villa)** 이에요. 1930년이에요.","값진 재료를 아낌없이 쓴 집이에요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**마노**: 투겐다트 주택에 쓰인 값진 돌 재료예요.","**크롬 도금**: 금속 표면에 크롬을 입혀 반짝이게 한 마감이에요.","**개방성과 폐쇄성의 대비**: 집의 앞뒤 한쪽은 열리고 다른 쪽은 닫혀 있는 것이에요."]},{"kind":"points","head":"빠뜨리면 안 되는 사실","items":["**마노**, 대리석, 옅은 유리색, **크롬 도금**한 철재 등 풍부한 재료를 사용했어요.","비대칭적인 단층의 **평지붕(Flat Roof)** 건물이라고 적혀 있어요.","전, 후면의 **개방성과 폐쇄성의 대비**가 극명해요."]},{"kind":"points","head":"사진에서 볼 것","items":["왼쪽 사진: 잔디 언덕 위 흰 건물이에요. 가로로 긴 유리창 띠가 트여 있어요.","오른쪽은 안내 포스터예요. 'VILLA TUGENDHAT', 'OTEVŘENA / IS OPEN' 이라고 적혀 있어요.","포스터 작은 글씨는 이 집을 체코의 유일한 근대건축 UNESCO 기념물로 소개해요.","포스터 사진 속 실내에는 반짝이는 기둥과 큰 유리창, 의자들이 보여요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**투겐다트 주택(Tugendhat Villa)** 의 위치와 연도로 옳은 것은 무엇일까요?","choices":["체코 브르노, 1930","독일 크레펠트, 1928","스페인 바르셀로나, 1929"],"a":0,"why":"체코 브르노, 1930년이에요."},{"kind":"check","q":"**투겐다트 주택(Tugendhat Villa)** 의 재료로 슬라이드에 적힌 것이 아닌 것은 무엇일까요?","choices":["**마노**","대리석","**크롬 도금**한 철재","**트레버틴(travertine)**"],"a":3,"why":"트레버틴은 바르셀로나 독일관의 두 벽체예요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["2쪽은 '작고 비대칭적인 단층의 평지붕 건물', 이 쪽은 '작고' 없이 '비대칭적인 단층의 평지붕 건물' 이에요.","그런데 16쪽 도면 제목은 2nd, 3rd FLOOR PLAN 이고 '침실들은 최상층에' 라는 문장도 있어요.","문장을 묻는 문제는 슬라이드 표현 '단층' 그대로 답하고, 그림과 다르다는 점만 알아 둬요.","**크롬 도금**은 **바르셀로나 박람회 독일관(Barcelona Pavilion)** 과 투겐다트 주택 둘 다에 나와요."]},{"kind":"english","head":"논술 답안: 투겐다트 주택","en":"투겐다트 주택(1930, 체코 브르노)은 마노, 대리석, 옅은 유리색, 크롬 도금한 철재 등 풍부한 재료를 사용한 비대칭적인 단층의 평지붕 건물로, 전, 후면의 개방성과 폐쇄성의 대비가 극명하다.","ko":"재료 넷, 모양(비대칭, 단층, 평지붕), 대비 세 덩어리예요.","tip":"'삼공(30), 공(0)간을 오닉스 한 장으로 나눔' 으로 연도를 외워요."}],"walk":{"head":null,"parts":[{"b":[0.04,0.06,0.17,0.07],"c":[0.025,0.04,0.2,0.11],"r":2.4242,"img":"img/U8/walk/p013_23_01.jpg","say":"제목: 투겐다트 주택(Tugendhat Villa)."},{"b":[0.03,0.175,0.48,0.1],"c":[0.006,0.159,0.528,0.132],"r":5.3333,"img":"img/U8/walk/p013_23_02.jpg","say":"마노, 대리석, 옅은 유리색, 크롬 도금한 철재 등 풍부한 재료 사용."},{"b":[0.03,0.29,0.35,0.05],"c":[0.0125,0.26,0.385,0.11],"r":4.6667,"img":"img/U8/walk/p013_23_03.jpg","say":"비대칭적인 단층의 평지붕 건물."},{"b":[0.03,0.35,0.46,0.05],"c":[0.007,0.32,0.506,0.11],"r":6.1333,"img":"img/U8/walk/p013_23_04.jpg","say":"전, 후면의 개방성과 폐쇄성의 대비가 극명."},{"b":[0.02,0.445,0.53,0.53],"c":[0,0.417,0.583,0.583],"r":1.3333,"img":"img/U8/walk/p013_23_05.jpg","say":"왼쪽 아래 사진: 잔디 언덕 위 흰 건물과 긴 유리창 띠예요."},{"b":[0.56,0.165,0.425,0.81],"c":[0.5325,0.109,0.4675,0.891],"r":0.6996,"img":"img/U8/walk/p013_23_06.jpg","say":"오른쪽: VILLA TUGENDHAT 안내 포스터예요."}]}},{"p":14,"title":"투겐다트 주택 외관, 체코 브르노, 1930","terms":["Tugendhat Villa","Flat Roof","개방성과 폐쇄성의 대비","Mass"],"pass1":[{"kind":"say","lines":["**투겐다트 주택(Tugendhat Villa)** 을 언덕 아래 잔디밭에서 올려다본 사진이에요.","큰 나무 뒤로 흰 집과 긴 유리벽이 보여요."]}],"pass2":[{"kind":"points","head":"이 사진에서 볼 것","items":["캡션: 미스 반 데어 로에, Tugendhat Villa, 체코 브르노, 1930.","아래층 앞면은 큰 유리창이 길게 이어져 안의 화분들이 비쳐 보여요.","위쪽은 창이 적은 흰 벽 **매스(Mass)** 예요. 오른쪽 위에 가로로 긴 창 하나가 있어요.","지붕은 평평해요. 13쪽에서 말한 **평지붕(Flat Roof)** 이에요.","잔디 언덕 사이로 흙길이 구불구불 올라가요."]},{"kind":"points","head":"13쪽 문장과 이어 보기","items":["이 쪽 사진 한 장 안에서도 열린 유리면과 닫힌 흰 벽이 함께 보여요.","13쪽 '**개방성과 폐쇄성의 대비**' 는 집의 앞면과 뒷면을 비교한 말이에요.","다음 15쪽에서 길 쪽 면을 보면 대비가 더 뚜렷해요."]},{"kind":"look","walked":1}],"pass3":[],"walk":{"head":null,"parts":[{"b":[0.03,0.025,0.905,0.9],"c":[0,0,0.9955,0.99],"r":1.3407,"img":"img/U8/walk/p014_22_01.jpg","say":"사진 전체: 언덕 아래에서 올려다본 투겐다트 주택이에요."},{"b":[0.395,0.405,0.37,0.13],"c":[0.3765,0.389,0.407,0.162],"r":3.3498,"img":"img/U8/walk/p014_22_02.jpg","say":"아래층의 긴 유리벽이에요. 안이 비쳐 보여요."},{"b":[0.59,0.3,0.225,0.12],"c":[0.578,0.284,0.249,0.152],"r":2.1842,"img":"img/U8/walk/p014_22_03.jpg","say":"위쪽의 흰 벽 덩어리와 가로로 긴 창이에요."},{"b":[0.46,0.95,0.42,0.035],"c":[0.439,0.89,0.462,0.11],"r":5.6,"img":"img/U8/walk/p014_22_04.jpg","say":"캡션: 미스 반 데어 로에, Tugendhat Villa, 체코 브르노, 1930."}]}},{"p":15,"title":"투겐다트 주택 사진 네 장 (곡면 유리벽, 길 쪽 흰 벽, 테라스)","terms":["Tugendhat Villa","개방성과 폐쇄성의 대비","Flat Roof","Mass"],"pass1":[{"kind":"say","lines":["**투겐다트 주택(Tugendhat Villa)** 을 여러 방향에서 찍은 사진 네 장이에요. 캡션도 글도 없어요.","둥근 유리벽, 길 쪽의 낮은 흰 벽, 기둥이 선 테라스가 보여요."]}],"pass2":[{"kind":"points","head":"이 사진에서 볼 것","items":["왼쪽 위: 휘어진 곡면 유리벽과 넓은 돌 바닥 테라스예요.","오른쪽 위: 길에서 본 모습이에요. 낮고 긴 흰 벽에 창이 적어요. 차와 사람들이 서 있어요.","왼쪽 아래: 길 쪽 흰 벽과 철망 울타리예요. 작은 창이 가로로 나 있어요.","오른쪽 아래: 지붕 덮인 테라스예요. 검은 기둥 하나가 서 있고 멀리 도시가 내려다보여요."]},{"kind":"points","head":"13쪽 문장과 이어 보기","items":["길 쪽은 흰 벽이 많고 창이 작아요. 14쪽 언덕 쪽은 유리벽이 길게 트였어요.","13쪽 '전, 후면의 **개방성과 폐쇄성의 대비**가 극명' 을 사진으로 확인하는 쪽이에요.","낮고 긴 **평지붕(Flat Roof)** 덩어리들이 비대칭으로 놓인 **매스(Mass)** 도 보여요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"13쪽 '**개방성과 폐쇄성의 대비**' 를 이 쪽과 14쪽 사진으로 보면 어느 쪽이 닫혀 있을까요?","choices":["길 쪽의 흰 벽 면","언덕 쪽의 긴 유리벽 면","두 면 모두 유리"],"a":0,"why":"길 쪽은 흰 벽이 많고 창이 작아요. 언덕 쪽은 유리벽이 길게 트였어요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["오른쪽 위 사진 위 파란 손글씨는 출처를 모르는 필기예요. 슬라이드 글이 아니므로 시험 사실로 외우지 않아요.","이 쪽에는 캡션이 없어요. 작품 이름은 13, 14쪽 캡션으로 외워요."]}],"walk":{"head":null,"parts":[{"b":[0.035,0.02,0.25,0.595],"c":[0.0225,0,0.275,0.6545],"r":0.5602,"img":"img/U8/walk/p015_22_01.jpg","say":"왼쪽 위: 곡면 유리벽과 테라스 바닥이에요."},{"b":[0.34,0.035,0.63,0.465],"c":[0.307,0.0117,0.693,0.5115],"r":1.8065,"img":"img/U8/walk/p015_22_02.jpg","say":"오른쪽 위: 길에서 본 낮고 긴 흰 벽이에요. 창이 적어요."},{"b":[0.02,0.615,0.46,0.345],"c":[0,0.5978,0.506,0.3795],"r":1.7778,"img":"img/U8/walk/p015_22_03.jpg","say":"왼쪽 아래: 흰 벽, 작은 가로 창, 철망 울타리예요."},{"b":[0.505,0.615,0.465,0.35],"c":[0.4818,0.5975,0.5115,0.385],"r":1.7714,"img":"img/U8/walk/p015_22_04.jpg","say":"오른쪽 아래: 기둥 하나가 선 지붕 덮인 테라스와 바깥 경치예요."}]}},{"p":16,"title":"투겐다트 주택의 평면과 스크린","terms":["Tugendhat Villa","펜트하우스","개방형 거실","onyx","Macassar ebony","칸막이 같은 벽","travertine"],"pass1":[{"kind":"say","lines":["집 안을 보는 쪽이에요. 글 네 줄, 모형 사진, 도면 두 장이 있어요.","거실은 넓게 트였고, 벽 대신 돌판 하나와 나무 곡선판으로 공간을 나눠요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**펜트하우스**: 맨 위층에 얹힌 집이에요.","**개방형 거실**: 벽으로 막지 않고 넓게 트인 거실이에요.","**오닉스(onyx)**: 거실과 서재를 나누는 대리석 스크린의 재료예요.","**마카사르 에보니(Macassar ebony)**: 다이닝 공간의 경계를 만드는 곡선 스크린의 재료예요."]},{"kind":"points","head":"빠뜨리면 안 되는 사실","items":["침실들은 최상층에 **펜트하우스**처럼 배치했어요.","넓은 **개방형 거실**이 있어요.","거실과 그 옆에 있는 서재 부분은 **오닉스(onyx)** 대리석 스크린으로만 구획했어요.","**마카사르 에보니(Macassar ebony)** 로 된 곡선의 스크린이 다이닝 공간의 경계를 만들어요."]},{"kind":"points","head":"모형과 도면에서 볼 것","items":["왼쪽 아래 흰 모형은 여러 층으로 쌓여 있고 층마다 테라스가 있어요.","오른쪽 위 도면 제목은 HOUSE TUGENDHAT BRNO 3rd FLOOR PLAN, 아래는 2nd FLOOR PLAN 이에요.","2nd FLOOR PLAN 에는 KITCHEN, PANTRY, LIVING SPACE 같은 방 이름이 보여요.","그 도면 가운데 반원 모양 선 안에 둥근 탁자와 의자들이 그려져 있어요. 글의 '곡선의 스크린' 과 모양이 닮았어요."]},{"kind":"bg","src":"8-3 바르셀로나와 이어 보기","lines":["바르셀로나 독일관도 막힌 벽 대신 **칸막이 같은 벽**을 세웠어요.","투겐다트 주택의 **오닉스(onyx)** 스크린과 곡선 스크린도 같은 생각이에요. 벽이 방을 가두지 않아요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"투겐다트 주택에서 거실과 서재를 나누는 스크린의 재료는 무엇일까요?","choices":["**오닉스(onyx)** 대리석","**마카사르 에보니(Macassar ebony)**","회색 염색 유리"],"a":0,"why":"거실과 서재는 오닉스 대리석 스크린으로만 구획했어요."},{"kind":"check","q":"다이닝 공간의 경계를 만드는 것은 무엇일까요?","choices":["오닉스 대리석 스크린","**마카사르 에보니(Macassar ebony)** 로 된 곡선의 스크린","**트레버틴(travertine)** 벽체"],"a":1,"why":"곡선 스크린은 마카사르 에보니예요."},{"kind":"check","q":"투겐다트 주택에서 침실들은 어디에 배치됐을까요?","choices":["최상층에 **펜트하우스**처럼","**개방형 거실** 옆 1층에","지하층에"],"a":0,"why":"침실들은 최상층에 펜트하우스처럼 배치했어요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["직선 스크린은 **오닉스(onyx)** (거실과 서재), 곡선 스크린은 **마카사르 에보니(Macassar ebony)** (다이닝)예요.","이 쪽 도면은 2nd, 3rd FLOOR PLAN 이고 침실은 최상층이에요. 13쪽 '단층' 표현과 맞지 않아요.","시험 문장은 슬라이드 그대로 외우고, 차이는 알아만 둬요. 글 옆 파란 손글씨는 출처를 모르는 필기예요."]},{"kind":"english","head":"논술 답안: 투겐다트 주택의 실내","en":"투겐다트 주택은 침실들을 최상층에 펜트하우스처럼 배치하고 넓은 개방형 거실을 두었으며, 거실과 서재는 오닉스 대리석 스크린으로만 구획하고 마카사르 에보니 곡선 스크린으로 다이닝 공간의 경계를 만들었다.","ko":"침실, 거실, 두 스크린의 재료와 역할을 넣어요.","tip":"'오닉스는 곧은 돌, 에보니는 굽은 나무' 로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.02,0.145,0.43,0.045],"c":[0,0.1125,0.473,0.11],"r":5.7333,"img":"img/U8/walk/p016_24_01.jpg","say":"침실들은 최상층에 펜트하우스처럼 배치."},{"b":[0.02,0.205,0.2,0.045],"c":[0.008,0.1725,0.224,0.11],"r":2.7152,"img":"img/U8/walk/p016_24_02.jpg","say":"넓은 개방형 거실."},{"b":[0.02,0.27,0.47,0.1],"c":[0,0.254,0.517,0.132],"r":5.2222,"img":"img/U8/walk/p016_24_03.jpg","say":"거실과 서재 부분은 오닉스(onyx) 대리석 스크린으로만 구획."},{"b":[0.02,0.385,0.47,0.095],"c":[0,0.369,0.517,0.127],"r":5.4278,"img":"img/U8/walk/p016_24_04.jpg","say":"마카사르 에보니(Macassar ebony)로 된 곡선의 스크린이 다이닝 공간의 경계."},{"b":[0.035,0.6,0.475,0.36],"c":[0.0112,0.582,0.5225,0.396],"r":1.7593,"img":"img/U8/walk/p016_24_05.jpg","say":"왼쪽 아래: 여러 층으로 쌓인 흰 모형이에요."},{"b":[0.55,0.17,0.405,0.74],"c":[0.5298,0.133,0.4455,0.814],"r":0.7297,"img":"img/U8/walk/p016_24_06.jpg","say":"오른쪽: 위는 3rd FLOOR PLAN, 아래는 2nd FLOOR PLAN 도면이에요."}]}},{"p":17,"title":"투겐다트 주택 실내: 크롬 기둥과 곡선 나무 스크린 (글자 없는 슬라이드)","terms":["Tugendhat Villa","크롬 도금","Macassar ebony","Less is more"],"pass1":[{"kind":"say","lines":["이 슬라이드에는 인쇄된 글자가 없어요. 큰 사진 한 장뿐이에요.","13-19쪽 **투겐다트 주택(Tugendhat Villa)** 묶음 안에 있는 실내 사진이에요.","왼쪽은 통유리 벽, 가운데는 반짝이는 기둥, 오른쪽은 나무 무늬 곡선 벽이에요.","그림을 붙이지 않고 재료가 꾸밈 역할을 해요. **적을수록 많다(Less is more)** 예요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**크롬 도금**: 금속 겉에 크롬을 입혀 거울처럼 반짝이게 한 마감이에요.","**마카사르 에보니(Macassar ebony)**: 다이닝 공간 경계를 만드는 곡선 스크린의 재료예요.","스크린: 공간을 나누는 칸막이 판이에요. 방을 꽉 막는 벽과 달라요."]},{"kind":"points","head":"사진에서 보이는 것","items":["왼쪽: 바닥부터 천장까지 큰 유리창이 길게 이어져요. 바깥 나무가 그대로 보여요.","가운데: 거울처럼 반짝이는 금속 기둥이 서 있어요.","13쪽 글의 재료 목록에 **크롬 도금** 한 철재가 있어요. 반짝이는 기둥이 그 모습이에요.","오른쪽: 나무 무늬가 뚜렷한 곡선 벽이 둥근 식탁과 의자를 감싸요.","16쪽 글: **마카사르 에보니(Macassar ebony)** 로 된 곡선의 스크린이 다이닝 공간의 경계를 만들어요.","사진 속 곡선 나무 벽과 식탁이 바로 그 다이닝 공간으로 보여요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**투겐다트 주택(Tugendhat Villa)** 에서 다이닝 공간의 경계를 만드는 곡선 스크린의 재료는 무엇일까요?","choices":["**오닉스(onyx)**","**마카사르 에보니(Macassar ebony)**","초록색 대리석"],"a":1,"why":"곡선 스크린은 마카사르 에보니예요. 오닉스는 거실과 서재를 나누는 대리석 스크린이에요."},{"kind":"warn","head":"이 쪽에서 조심할 점","items":["이 슬라이드에는 캡션이 없어요. 이름은 13-16쪽에서 가져와요.","사진 위 파란 손글씨는 누가 쓴 필기인지 알 수 없어요. 슬라이드 내용으로 외우지 않아요.","재료와 장식에 관한 시험 문장은 19쪽 슬라이드 글로 외워요."]}],"walk":{"head":null,"parts":[{"b":[0.057,0.055,0.34,0.875],"c":[0.0398,0.0112,0.3743,0.9625],"r":0.5185,"img":"img/U8/walk/p017_22_01.jpg","say":"왼쪽: 바닥부터 천장까지 이어진 유리창이에요. 바깥 나무가 보여요."},{"b":[0.555,0.055,0.055,0.72],"c":[0.4285,0.019,0.308,0.792],"r":0.5185,"img":"img/U8/walk/p017_22_02.jpg","say":"가운데: 거울처럼 반짝이는 금속 기둥이에요."},{"b":[0.65,0.27,0.28,0.4],"c":[0.636,0.25,0.308,0.44],"r":0.9333,"img":"img/U8/walk/p017_22_03.jpg","say":"오른쪽: 나무 무늬가 그대로 드러난 곡선 벽이에요."},{"b":[0.61,0.57,0.32,0.22],"c":[0.594,0.554,0.352,0.252],"r":1.8624,"img":"img/U8/walk/p017_22_04.jpg","say":"곡선 벽 앞의 둥근 식탁과 의자들이에요. 다이닝 공간이에요."}]}},{"p":18,"title":"투겐다트 주택 실내: 유리벽과 반짝이는 기둥 (글자 없는 슬라이드)","terms":["Tugendhat Villa","크롬 도금","투명성","Barcelona Pavilion","Farnsworth house"],"pass1":[{"kind":"say","lines":["사진 세 장이에요. 이번에도 인쇄된 글자는 없어요.","**투겐다트 주택(Tugendhat Villa)** 의 유리벽 쪽 실내로 보여요.","유리 너머로 하늘과 나무가 보이고, 반짝이는 기둥에 주변이 비쳐요."]},{"kind":"analogy","head":"유리 진열장 속 거실","scene":"투명한 진열장 안에 앉아 있으면 바깥 정원이 내 방 벽처럼 보이죠.","map":[["투명한 진열장 벽","바닥부터 천장까지 이어진 유리벽"],["반짝이는 진열장 모서리","**크롬 도금** 철재처럼 빛나는 기둥"],["안과 밖이 이어져 보임","**투명성**"]]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**투명성**: 유리와 반사로 안과 밖이 비쳐 보이는 성질이에요.","12쪽 **바르셀로나 박람회 독일관(Barcelona Pavilion)** 에서 처음 나온 말이에요.","그곳은 채색된 유리, 빛나는 대리석, **크롬 도금** 가구 프레임의 광택으로 **투명성** 을 표현했어요."]},{"kind":"points","head":"사진에서 보이는 것","items":["위 사진: 유리벽에 하늘과 나무가 비쳐요. 안쪽에 흰 의자들이 줄지어 있어요.","왼쪽 아래 사진: 반짝이는 기둥이 여러 개 서 있고, 빨간 긴 의자가 놓여 있어요.","오른쪽 사진: 긴 유리벽을 따라 기둥이 한 줄로 서 있어요. 바닥에 햇빛 줄무늬가 져요.","벽 대신 유리라서 바깥 정원과 실내가 한 공간처럼 보여요.","13쪽 글의 재료 가운데 옅은 유리색, **크롬 도금** 한 철재가 이 사진에 잘 보여요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"warn","head":"이 쪽에서 조심할 점","items":["투겐다트 쪽 슬라이드 글에는 '투명성' 이라는 낱말이 없어요.","**투명성** 은 12쪽 **바르셀로나 박람회 독일관(Barcelona Pavilion)** 과 22쪽 **판스워스 하우스(Farnsworth house)** 글에 나와요.","사진 위 파란 손글씨는 누가 쓴 필기인지 알 수 없어요. 슬라이드 내용으로 외우지 않아요."]}],"walk":{"head":null,"parts":[{"b":[0.177,0.059,0.425,0.424],"c":[0.1557,0.0378,0.4675,0.4664],"r":1.3365,"img":"img/U8/walk/p018_22_01.jpg","say":"위 사진: 유리벽에 하늘과 나무가 비치고, 안쪽에 흰 의자들이 있어요."},{"b":[0.021,0.51,0.597,0.448],"c":[0,0.4876,0.6567,0.4928],"r":1.7768,"img":"img/U8/walk/p018_22_02.jpg","say":"왼쪽 아래: 반짝이는 기둥 여러 개와 빨간 긴 의자예요."},{"b":[0.657,0.217,0.311,0.735],"c":[0.6414,0.1803,0.3421,0.8085],"r":0.5642,"img":"img/U8/walk/p018_22_03.jpg","say":"오른쪽: 긴 유리벽을 따라 기둥이 한 줄로 서 있어요."}]}},{"p":19,"title":"공간의 영속성, 절대적 필요성, 소재의 패턴이 장식을 대신","terms":["공간의 영속성","absolutely necessary","onyx","Macassar ebony","Tugendhat Villa","Less is more"],"pass1":[{"kind":"analogy","head":"무늬를 그리지 않은 고운 천","scene":"그림을 그려 넣지 않아도 천의 결이 고우면 멋진 옷이 되죠.","map":[["옷에 그려 넣은 그림","붙여 꾸민 장식"],["천의 고운 결","소재들의 패턴과 질감"],["꼭 필요한 옷만 입기","**절대적 필요성(absolutely necessary)** 에 의한 가구 배치"]]},{"kind":"say","lines":["천장과 바닥은 밋밋하게, 가구는 꼭 필요한 것만, 장식은 재료의 무늬로.","**적을수록 많다(Less is more)** 가 **투겐다트 주택(Tugendhat Villa)** 안에서 이렇게 나타나요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**공간의 영속성**: 천장과 바닥을 밋밋하게 남겨 공간이 오래 변하지 않게 하려는 개념이에요.","**절대적 필요성(absolutely necessary)**: 꼭 필요한 것만 둔다는 가구 배치 원칙이에요.","**오닉스(onyx)**: 거실과 서재를 나누는 대리석 스크린의 재료예요. 값비싼 재료예요.","궁극적: 가장 끝까지 간, 최고의 라는 뜻이에요."]},{"kind":"points","head":"슬라이드 글 세 줄","items":["1. 천장과 바닥 역시 건축적 요소를 가능한 배제하여 밋밋하게 남겨 놓았어요.","그 까닭은 **공간의 영속성** 이라는 개념을 유지하려는 거예요.","2. **절대적 필요성(absolutely necessary)** 에 의한 가구 배치와 **오닉스(onyx)** 같은 값비싼 재료의 우아함이 조화돼요.","그래서 궁극적 미와 화려함을 줘요.","3. 소재들의 패턴과 질감이 장식을 대신하고, 공간적 요소들의 추상적인 배열을 강조해요."]},{"kind":"points","head":"사진에서 보이는 것","items":["왼쪽: 큰 물결무늬 돌 벽 앞에 의자들과 빨간 긴 의자가 놓여 있어요.","오른쪽: 같은 무늬 돌 벽 앞에 책상과 의자, 오른쪽 끝에 나무 무늬 곡선 벽이 보여요.","16쪽 글의 **오닉스(onyx)** 대리석 스크린과 **마카사르 에보니(Macassar ebony)** 곡선 스크린으로 보여요.","벽에 그림이나 조각 장식이 없어요. 돌과 나무의 무늬가 곧 장식이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**투겐다트 주택(Tugendhat Villa)** 에서 천장과 바닥을 밋밋하게 남긴 까닭은 무엇일까요?","choices":["**공간의 영속성** 이라는 개념을 유지하려고","**하나의 섬(island)** 을 만들려고","공사 기간을 줄이려고"],"a":0,"why":"슬라이드 글: 이는 공간의 영속성이라는 개념을 유지하고자 함."},{"kind":"check","q":"소재들의 패턴과 질감이 대신하는 것은 무엇일까요?","choices":["구조","장식","가구"],"a":1,"why":"소재들의 패턴과 질감이 장식을 대신해요. 그리고 공간적 요소들의 추상적인 배열을 강조해요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["'천장과 바닥을 화려하게' 로 바꾼 O/X 함정을 조심해요. 천장과 바닥은 밋밋해요.","화려함은 가구 배치와 **오닉스(onyx)** 같은 값비싼 재료의 우아함에서 나와요."]},{"kind":"english","head":"논술 답안: 투겐다트 주택의 실내","en":"투겐다트 주택은 천장과 바닥의 건축적 요소를 배제하여 공간의 영속성을 유지하고, 절대적 필요성에 의한 가구 배치와 오닉스 같은 값비싼 재료로 궁극적 미와 화려함을 주며, 소재의 패턴과 질감이 장식을 대신한다.","ko":"밋밋한 천장, 바닥(영속성) → 가구(절대적 필요성) → 재료(오닉스) → 무늬가 장식 순서예요.","tip":"'밋밋, 필요, 오닉스, 무늬' 네 낱말을 세어서 외워요."}],"walk":{"head":null,"parts":[{"b":[0.065,0.065,0.88,0.1],"c":[0.021,0.0172,0.968,0.1956],"r":6.5985,"img":"img/U8/walk/p019_23_01.jpg","say":"1. 천장과 바닥은 밋밋하게. 공간의 영속성을 유지하려는 거예요."},{"b":[0.065,0.185,0.88,0.1],"c":[0.021,0.1372,0.968,0.1956],"r":6.5985,"img":"img/U8/walk/p019_23_02.jpg","say":"2. 절대적 필요성에 의한 가구 배치, 오닉스 같은 값비싼 재료의 우아함이에요."},{"b":[0.065,0.3,0.88,0.095],"c":[0.021,0.2497,0.968,0.1956],"r":6.5985,"img":"img/U8/walk/p019_23_03.jpg","say":"3. 소재들의 패턴과 질감이 장식을 대신해요."},{"b":[0.019,0.439,0.47,0.453],"c":[0,0.4163,0.517,0.4983],"r":1.3834,"img":"img/U8/walk/p019_23_04.jpg","say":"왼쪽 사진: 물결무늬 돌 벽 앞의 의자들이에요."},{"b":[0.51,0.439,0.474,0.453],"c":[0.4786,0.4163,0.5214,0.4983],"r":1.3951,"img":"img/U8/walk/p019_23_05.jpg","say":"오른쪽 사진: 돌 벽 앞 책상, 오른쪽 끝에 나무 무늬 곡선 벽이에요."}]}},{"p":20,"title":"전후 모더니즘: 판스워스 하우스(Farnsworth house), 1950","terms":["전후 모더니즘","Farnsworth house","Ludwig Mies van der Rohe","Walter Gropius","Functionalism","Mass","Tugendhat Villa"],"pass1":[{"kind":"say","lines":["새 묶음이 시작돼요. 초록 제목이 **전후 모더니즘** 이에요.","첫 작품은 **판스워스 하우스(Farnsworth house)**, 미국 Plano, IL, 1950년이에요.","숲속 잔디 위에 하얀 기둥이 유리 상자를 살짝 들어 올렸어요."]},{"kind":"points","head":"이 사람 다시 보기","items":["**미스 반 데어 로에(Ludwig Mies van der Rohe)**, 1886-1969년이에요.","**발터 그로피우스(Walter Gropius)** 와 함께 독일의 대표적 **기능주의(Functionalism)** 건축가예요.","앞 묶음까지는 독일과 체코였는데, 이제 캡션의 장소가 미국이에요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**전후 모더니즘**: 전쟁 뒤의 모더니즘이에요. 8단원 뒤쪽 묶음의 제목이에요.","**매스(Mass)**: 건물이 이루는 큰 덩어리예요.","평면도: 건물을 위에서 내려다보고 바닥 모양을 그린 그림이에요."]},{"kind":"points","head":"이 그림에서 볼 것","items":["제목은 **판스워스 하우스(Farnsworth house)** 예요.","캡션: 미스 반 데어 로에, 판스워스 하우스, Plano, IL, USA, 1950.","오른쪽 위 평면도: 격자 위에 직사각형 두 개가 어긋나게 붙어 있어요.","위쪽 큰 직사각형 안에 가구와 작은 칸이 그려져 있고, 아래쪽은 거의 비어 있어요.","왼쪽 사진: 지붕 아래 넓은 바닥판과 계단이에요. 바닥판이 땅에서 떠 있어요.","오른쪽 사진: 옆에서 본 모습이에요. 흰 기둥이 유리 **매스(Mass)** 를 땅 위로 받쳐 들어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**판스워스 하우스(Farnsworth house)** 의 장소와 연도로 옳은 것은 무엇일까요?","choices":["체코 브르노, 1930","Plano, IL, USA, 1950","미국 시카고, 1951"],"a":1,"why":"체코 브르노 1930은 투겐다트 주택, 미국 시카고 1951은 레이크쇼어 드라이브 아파트예요."},{"kind":"check","q":"**미스 반 데어 로에(Ludwig Mies van der Rohe)** 와 함께 독일의 대표적 **기능주의(Functionalism)** 건축가로 꼽히는 사람은?","choices":["**발터 그로피우스(Walter Gropius)**","한스 샤로운","르 코르뷔지에"],"a":0,"why":"8단원 첫 슬라이드 문장이에요. 4단원 바우하우스의 그 그로피우스예요."},{"kind":"warn","head":"손글씨 조심","items":["이 쪽에는 평면과 사진 위에 파란 펜 필기가 많아요.","사진 위 파란 손글씨는 누가 쓴 필기인지 알 수 없어요. 슬라이드 내용으로 외우지 않아요.","시험 대비는 인쇄된 제목과 캡션만으로 해요."]}],"walk":{"head":null,"parts":[{"b":[0.045,0.055,0.19,0.05],"c":[0.033,0.025,0.214,0.11],"r":2.5939,"img":"img/U8/walk/p020_22_01.jpg","say":"묶음 제목: 전후 모더니즘."},{"b":[0.035,0.365,0.33,0.04],"c":[0.0185,0.33,0.363,0.11],"r":4.4,"img":"img/U8/walk/p020_22_02.jpg","say":"작품 이름: 판스워스 하우스(Farnsworth house)."},{"b":[0.505,0.08,0.43,0.33],"c":[0.4835,0.0635,0.473,0.363],"r":1.7374,"img":"img/U8/walk/p020_22_03.jpg","say":"평면도: 직사각형 두 개가 어긋나게 붙어 있어요."},{"b":[0.016,0.448,0.452,0.452],"c":[0,0.4254,0.4972,0.4972],"r":1.3333,"img":"img/U8/walk/p020_22_04.jpg","say":"왼쪽 사진: 땅에서 뜬 바닥판, 넓은 지붕, 계단이에요."},{"b":[0.484,0.448,0.433,0.452],"c":[0.4624,0.4254,0.4763,0.4972],"r":1.2773,"img":"img/U8/walk/p020_22_05.jpg","say":"오른쪽 사진: 흰 기둥이 유리 상자를 들어 올린 옆모습이에요."},{"b":[0.035,0.905,0.45,0.035],"c":[0.0125,0.8675,0.495,0.11],"r":6.0,"img":"img/U8/walk/p020_22_06.jpg","say":"캡션: 미스 반 데어 로에, 판스워스 하우스, Plano, IL, USA, 1950."}]}},{"p":21,"title":"판스워스 하우스: 정제된 디자인의 극단적인 예","terms":["Farnsworth house","정제된 디자인","Mass","철골 구조","오픈 리빙 스페이스","island"],"pass1":[{"kind":"analogy","head":"숲속 유리 진열장","scene":"잔디 위에 투명한 유리 진열장을 살짝 띄워 놓았다고 상상해 보세요.","map":[["진열장을 받친 다리","**철골 구조**"],["투명한 유리판","안과 밖을 최소한으로 나누는 유리면"],["진열장 안의 작은 상자 하나","**하나의 섬(island)**"]]},{"kind":"say","lines":["필요한 것만 남기고 나머지는 다 지운 집이에요.","그래서 **판스워스 하우스(Farnsworth house)** 를 **정제된 디자인** 의 극단적인 예라고 해요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**정제된 디자인**: 필요한 최소한만 남기고 불필요한 요소는 모두 지운 디자인이에요.","**철골 구조**: 강철 뼈대로 건물을 받치는 구조예요.","**오픈 리빙 스페이스**: 벽 없이 하나로 트인 생활 공간이에요.","**하나의 섬(island)**: 벽난로, 욕실들, 다용도 공간을 몰아넣은 벽 덩어리예요."]},{"kind":"points","head":"슬라이드 글 네 줄","items":["1. 주거공간에 필요한 최소한의 요소만 남기고 불필요한 요소는 모두 삭제된, **정제된 디자인** 의 극단적인 예.","2. 대지로부터 띄워 올려진 **매스(Mass)** 는 **철골 구조** 로 지탱돼요.","구조체 외에 매스를 이루는 요소는 내, 외부를 최소한으로 경계 지워 주는 유리면이에요.","3. 네 면이 모두 유리로 된 주말 전원 주택에 **오픈 리빙 스페이스** 의 개념을 적용했어요.","4. 왼쪽 벽 요소들은 **하나의 섬(island)** 을 위한 것이에요.","그 안에 벽난로와 욕실들, 다용도 공간들이 들어가고, 반대편에는 부엌을 배치했어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**판스워스 하우스(Farnsworth house)** 의 **하나의 섬(island)** 안에 들어간 것이 아닌 것은 무엇일까요?","choices":["벽난로","욕실들","부엌"],"a":2,"why":"부엌은 섬의 반대편에 배치돼요. 섬 안에는 벽난로, 욕실들, 다용도 공간이 있어요."},{"kind":"english","head":"논술 답안: 판스워스 하우스","en":"판스워스 하우스(Plano, IL, USA, 1950)는 대지로부터 띄워 올려진 매스를 철골 구조로 지탱하고, 네 면이 모두 유리로 된 주말 전원 주택에 오픈 리빙 스페이스를 적용한 정제된 디자인의 극단적인 예이다.","ko":"띄운 매스(철골) → 네 면 유리 → 오픈 리빙 스페이스 → 정제된 디자인 순서예요.","tip":"섬 안 세 가지(벽난로, 욕실들, 다용도 공간)와 반대편 부엌을 덧붙이면 더 좋아요."}],"walk":{"head":null,"parts":[{"b":[0.075,0.06,0.88,0.1],"c":[0.031,0.0122,0.968,0.1956],"r":6.5985,"img":"img/U8/walk/p021_22_01.jpg","say":"1. 정제된 디자인의 극단적인 예."},{"b":[0.075,0.175,0.88,0.1],"c":[0.031,0.1272,0.968,0.1956],"r":6.5985,"img":"img/U8/walk/p021_22_02.jpg","say":"2. 띄워 올려진 매스를 철골 구조가 지탱, 나머지는 유리면."},{"b":[0.075,0.29,0.8,0.05],"c":[0.035,0.2261,0.88,0.1778],"r":6.5992,"img":"img/U8/walk/p021_22_03.jpg","say":"3. 네 면이 모두 유리인 주말 전원 주택, 오픈 리빙 스페이스."},{"b":[0.075,0.355,0.88,0.1],"c":[0.031,0.3072,0.968,0.1956],"r":6.5985,"img":"img/U8/walk/p021_22_04.jpg","say":"4. 하나의 섬(island): 벽난로, 욕실들, 다용도 공간. 반대편은 부엌."},{"b":[0.224,0.479,0.512,0.502],"c":[0.1984,0.4478,0.5632,0.5522],"r":1.3599,"img":"img/U8/walk/p021_22_05.jpg","say":"사진: 땅에서 뜬 바닥판으로 계단이 두 번 꺾여 올라가요."}]}},{"p":22,"title":"판스워스 하우스: 비움, 단순 기하 형태, 투명성과 모호성","terms":["Farnsworth house","비움","벽체","단순 기하 형태","물성","투명성","모호성","Tugendhat Villa","Less is more"],"pass1":[{"kind":"say","lines":["이 쪽의 열쇠말은 **비움** 이에요.","벽을 거의 다 없애서 안을 비웠더니 미니멀한 효과가 오히려 커졌어요.","**적을수록 많다(Less is more)** 를 집 한 채로 보여 준 셈이에요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**비움**: 내부공간을 비워 미니멀한 효과를 극대화하는 수단이에요.","**단순 기하 형태**: 네모, 직선처럼 단순한 도형 모양이에요.","**물성**: 재료가 가진 그대로의 성질과 느낌이에요.","**모호성**: 빛에 비쳐 안과 밖의 경계가 흐릿해지는 성질이에요."]},{"kind":"points","head":"슬라이드 글 세 줄","items":["1. 미니멀한 효과는 내부공간의 '**비움**' 이라는 수단으로 극대화.","2. 최소한의 차단이 필요한 공간을 빼고 내부의 **벽체** 는 제거됐어요.","설비가 필요한 부엌 및 화장실 외의 기능은 매우 유동적이에요.","3. **단순 기하 형태** 를 추구하며, **물성** 만이 외부로 드러나는 콘크리트나 유리를 써요.","빛에 의한 **투명성** 과 **모호성** 으로 건물의 존재감 자체를 극대화하려는 의도예요."]},{"kind":"compare","head":"두 집 비교 (슬라이드 글로만)","cols":["","투겐다트 주택","판스워스 하우스"],"rows":[["장소, 연도","체코 브르노, 1930","Plano, IL, USA, 1950"],["슬라이드가 말한 모양","비대칭적인 단층의 평지붕 건물","네 면이 모두 유리로 된 주말 전원 주택"],["재료","마노, 대리석, 옅은 유리색, 크롬 도금한 철재","콘크리트나 유리"],["열쇠말","전, 후면의 개방성과 폐쇄성의 대비","비움, 투명성과 모호성"]]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**판스워스 하우스(Farnsworth house)** 에서 설비가 필요해 기능이 정해진 곳은 어디일까요?","choices":["부엌 및 화장실","거실과 서재","침실과 테라스"],"a":0,"why":"설비가 필요한 부엌 및 화장실 외의 기능은 매우 유동적이에요."},{"kind":"check","q":"빛에 의한 무엇으로 건물의 존재감 자체를 극대화하려 했을까요?","choices":["**투명성** 과 **모호성**","대칭과 축","장식과 색채"],"a":0,"why":"빛에 의한 투명성과 모호성이에요. 재료는 물성만 드러나는 콘크리트나 유리예요."},{"kind":"english","head":"논술 답안: 판스워스 하우스의 비움","en":"판스워스 하우스는 최소한의 차단이 필요한 공간 외의 내부 벽체를 제거한 비움으로 미니멀한 효과를 극대화하고, 단순 기하 형태와 콘크리트나 유리를 써서 빛에 의한 투명성과 모호성으로 건물의 존재감을 극대화하였다.","ko":"비움(벽체 제거) → 단순 기하 형태 → 콘크리트, 유리 → 투명성과 모호성 순서예요.","tip":"'투명성과 모호성' 은 짝으로 붙여서 외워요."}],"walk":{"head":null,"parts":[{"b":[0.075,0.055,0.62,0.045],"c":[0.044,0.0086,0.682,0.1378],"r":6.5989,"img":"img/U8/walk/p022_23_01.jpg","say":"1. 미니멀한 효과는 비움이라는 수단으로 극대화."},{"b":[0.075,0.115,0.87,0.095],"c":[0.0315,0.0658,0.957,0.1933],"r":6.6011,"img":"img/U8/walk/p022_23_02.jpg","say":"2. 내부 벽체 제거. 부엌, 화장실 외의 기능은 매우 유동적."},{"b":[0.075,0.225,0.87,0.145],"c":[0.0315,0.2008,0.957,0.1933],"r":6.6011,"img":"img/U8/walk/p022_23_03.jpg","say":"3. 단순 기하 형태, 콘크리트나 유리, 투명성과 모호성."},{"b":[0.204,0.39,0.59,0.54],"c":[0.1745,0.363,0.649,0.594],"r":1.4568,"img":"img/U8/walk/p022_23_04.jpg","say":"사진: 숲 앞에 흰 기둥이 낮게 띄운 긴 상자예요."},{"b":[0.24,0.945,0.44,0.035],"c":[0.218,0.89,0.484,0.11],"r":5.8667,"img":"img/U8/walk/p022_23_05.jpg","say":"캡션: 미스 반 데어 로에, 판스워스 하우스, Plano, IL, USA, 1950."}]}},{"p":23,"title":"크라운 홀, IIT, 시카고, 1955 (설명 글 없는 슬라이드)","terms":["크라운 홀","Ludwig Mies van der Rohe","전후 모더니즘","Farnsworth house"],"pass1":[{"kind":"say","lines":["**크라운 홀** 이에요. 캡션은 미스 반 데어 로에, 크라운 홀, IIT, 시카고, 1955.","슬라이드에 설명 글은 없어요. 사진 두 장과 도면 두 장뿐이에요.","길고 네모난 건물의 벽이 거의 다 유리예요."]}],"pass2":[{"kind":"points","head":"사진과 도면에서 보이는 것","items":["위 흑백 사진: 검은 뼈대 사이에 큰 유리가 끼워진 긴 건물이에요. 앞에 넓은 계단이 있어요.","아래 컬러 사진: 정면이에요. 지붕 위로 검은 뼈대가 솟아 있고, 가운데로 계단이 올라가요.","오른쪽 위 도면: 칸막이가 거의 없는 넓은 한 공간이에요. 위아래에 입구가 있어요.","오른쪽 아래 도면: 여러 방으로 나뉜 평면이에요. 층 이름은 슬라이드에 없어요.","**판스워스 하우스(Farnsworth house)** 처럼 땅에서 몇 계단 올라가서 들어가요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**크라운 홀** 의 캡션으로 옳은 것은 무엇일까요?","choices":["IIT, 시카고, 1955","독일 베를린, 1968","Plano, IL, USA, 1950"],"a":0,"why":"크라운 홀은 IIT, 시카고, 1955예요. 1968 베를린은 신 국립미술관이에요."},{"kind":"warn","head":"이 쪽에서 조심할 점","items":["**크라운 홀** 은 설명 글이 없어요. 캡션(IIT, 시카고, 1955)을 그대로 외워요.","도면의 층 이름이나 용도는 슬라이드에 없어요. 짐작해서 쓰지 않아요.","도면 옆 파란 손글씨도 출처를 모르는 필기예요."]}],"walk":{"head":null,"parts":[{"b":[0.05,0.062,0.095,0.04],"c":[0,0.027,0.2,0.11],"r":2.4242,"img":"img/U8/walk/p023_21_01.jpg","say":"제목: 크라운 홀."},{"b":[0.21,0.118,0.348,0.358],"c":[0.1926,0.1001,0.3828,0.3938],"r":1.2961,"img":"img/U8/walk/p023_21_02.jpg","say":"위 흑백 사진: 검은 뼈대와 큰 유리, 앞의 넓은 계단이에요."},{"b":[0.025,0.515,0.537,0.407],"c":[0,0.4947,0.5907,0.4477],"r":1.7592,"img":"img/U8/walk/p023_21_03.jpg","say":"아래 사진: 지붕 위로 솟은 검은 뼈대, 가운데 계단이에요."},{"b":[0.627,0.355,0.32,0.305],"c":[0.611,0.339,0.352,0.337],"r":1.3927,"img":"img/U8/walk/p023_21_04.jpg","say":"위 도면: 칸막이가 거의 없는 넓은 한 공간이에요."},{"b":[0.627,0.7,0.32,0.25],"c":[0.611,0.684,0.352,0.282],"r":1.6643,"img":"img/U8/walk/p023_21_05.jpg","say":"아래 도면: 여러 방으로 나뉜 평면이에요."},{"b":[0.06,0.943,0.36,0.033],"c":[0.042,0.89,0.396,0.11],"r":4.8,"img":"img/U8/walk/p023_21_06.jpg","say":"캡션: 미스 반 데어 로에, 크라운 홀, IIT, 시카고, 1955."}]}},{"p":24,"title":"1922년의 계획안 두 개: 콘크리트 오피스빌딩과 프리드리히가 마천루","terms":["계획안","콘크리트 오피스빌딩 계획안","프리드리히가 마천루 계획안","마천루","brick villa","크라운 홀","전후 모더니즘"],"pass1":[{"kind":"say","lines":["이번 쪽은 시간을 거꾸로 돌려요. 1922년 **계획안** 두 개예요.","**계획안** 은 실제로 지은 건물이 아니라 그림과 모형으로 낸 설계 제안이에요.","두 그림 모두 아주 키가 큰 건물이에요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**계획안**: 아직 지은 건물이 아니라 도면과 그림으로 낸 설계 제안이에요.","**마천루**: 하늘에 닿을 듯 아주 높은 건물이에요.","프리드리히가: 독일 베를린의 거리 이름이에요. '가' 는 거리라는 뜻이에요."]},{"kind":"points","head":"두 캡션","items":["왼쪽: 미스 반 데어 로에, **콘크리트 오피스빌딩 계획안**, 1922.","오른쪽: 미스 반 데어 로에, **프리드리히가 마천루 계획안**, 독일 베를린, 1922.","도시 이름(독일 베를린)이 붙은 쪽은 **프리드리히가 마천루 계획안** 이에요.","왼쪽 그림: 옛 거리 끝에 뾰족하고 높은 건물이 서 있어요. 전깃줄이 앞을 지나가요.","오른쪽 그림: 굽은 면이 여러 겹 겹친 높은 모형이에요. 층마다 얇은 판이 보여요."]},{"kind":"compare","head":"미스 작품 연대순 (8단원 슬라이드 연도)","cols":["연도","작품"],"rows":[["1922","**프리드리히가 마천루 계획안**, **콘크리트 오피스빌딩 계획안**"],["1923","**브릭 빌라(brick villa)** 계획안"],["1927","바이센호프 주거단지 4층 아파트"],["1929","**바르셀로나 박람회 독일관(Barcelona Pavilion)**"],["1930","**투겐다트 주택(Tugendhat Villa)**"],["1950","**판스워스 하우스(Farnsworth house)**"],["1951","**레이크쇼어 드라이브 아파트(Lake shore drive)**"],["1955","**크라운 홀**"],["1968","**베를린 신 국립미술관(new national gallery)**"]]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"캡션에 '독일 베를린' 이 붙은 1922년 계획안은 무엇일까요?","choices":["**콘크리트 오피스빌딩 계획안**","**프리드리히가 마천루 계획안**","**브릭 빌라(brick villa)** 계획안"],"a":1,"why":"프리드리히가 마천루 계획안, 독일 베를린, 1922예요. 브릭 빌라 계획안은 1923년이에요."},{"kind":"warn","head":"순서 함정","items":["1922년 **계획안** 은 슬라이드에서 **크라운 홀**(1955) 바로 다음, **전후 모더니즘** 묶음 안에 나와요.","연도로는 8단원에 나온 미스 작품 가운데 가장 이른 해예요(1922 → 1923 **브릭 빌라(brick villa)**).","그림만 보면 두 건물 모두 유리처럼 비쳐 보여요. 이름은 캡션 그대로 외워요."]}],"walk":{"head":null,"parts":[{"b":[0.077,0.068,0.387,0.81],"c":[0.0577,0.0275,0.4257,0.891],"r":0.637,"img":"img/U8/walk/p024_23_01.jpg","say":"왼쪽 그림: 옛 거리 끝에 뾰족하고 높은 건물이 서 있어요."},{"b":[0.077,0.912,0.365,0.06],"c":[0.0588,0.887,0.4015,0.11],"r":4.8667,"img":"img/U8/walk/p024_23_02.jpg","say":"왼쪽 캡션: 콘크리트 오피스빌딩 계획안, 1922."},{"b":[0.555,0.04,0.34,0.836],"c":[0.538,0,0.374,0.9196],"r":0.5423,"img":"img/U8/walk/p024_23_03.jpg","say":"오른쪽 그림: 굽은 면이 겹친 높은 모형이에요."},{"b":[0.567,0.912,0.365,0.075],"c":[0.5487,0.89,0.4015,0.11],"r":4.8667,"img":"img/U8/walk/p024_23_04.jpg","say":"오른쪽 캡션: 프리드리히가 마천루 계획안, 독일 베를린, 1922."}]}},{"p":25,"title":"레이크쇼어 드라이브 아파트(Lake shore drive), 미국 시카고, 1951","terms":["Lake shore drive","Ludwig Mies van der Rohe","크라운 홀","마천루"],"pass1":[{"kind":"say","lines":["**레이크쇼어 드라이브 아파트(Lake shore drive)** 예요. 미국 시카고, 1951년이에요.","철과 유리로 지은 아주 높은 아파트, 초고층아파트예요.","높은 곳에 살면서 도시의 가게와 식당을 편하게 쓰는 집이에요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["초고층아파트: 아주 높은 아파트예요. 24쪽의 **마천루** 처럼 하늘로 높이 솟아요.","위락시설: 놀고 즐기는 시설이에요."]},{"kind":"points","head":"슬라이드 글 두 줄과 그림","items":["1. 철과 유리의 초고층아파트.","2. 도시의 상점, 레스토랑, 위락시설 등을 편리하게 이용.","왼쪽 항공사진: 호숫가 큰길 옆에 짙은 색 고층 건물 두 동이 어긋나게 서 있어요.","오른쪽 책 그림: 두 동의 평면이에요. 남쪽 타워, 북쪽 타워, 거실, 침실 같은 글자가 적혀 있어요.","책 그림 캡션: 시카고의 레이크 쇼어 드라이브 아파트(1950-1951년).","같은 시카고에 **크라운 홀**(1955)도 있어요. 두 작품 다 미국 시카고예요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**레이크쇼어 드라이브 아파트(Lake shore drive)** 를 설명하는 슬라이드 글은 무엇일까요?","choices":["철과 유리의 초고층아파트","네 면이 모두 유리로 된 주말 전원 주택","비대칭적인 단층의 평지붕 건물"],"a":0,"why":"두 번째는 판스워스 하우스, 세 번째는 투겐다트 주택이에요."},{"kind":"warn","head":"연도 두 개","items":["슬라이드 캡션은 1951, 그림 속 책 캡션은 1950-1951년이에요.","시험 답은 슬라이드 캡션 1951로 써요.","슬라이드 글은 '상점 레스토랑 위락시설' 을 쉼표 없이 붙여 썼어요. 세 가지 시설이에요."]}],"walk":{"head":null,"parts":[{"b":[0.052,0.083,0.225,0.035],"c":[0.04,0.0455,0.249,0.11],"r":3.0182,"img":"img/U8/walk/p025_22_01.jpg","say":"제목: Lake shore drive 아파트."},{"b":[0.052,0.162,0.545,0.11],"c":[0.0247,0.146,0.5995,0.142],"r":5.6291,"img":"img/U8/walk/p025_22_02.jpg","say":"철과 유리의 초고층아파트, 도시의 상점, 레스토랑, 위락시설을 편리하게."},{"b":[0.012,0.363,0.484,0.5],"c":[0,0.338,0.5324,0.55],"r":1.2907,"img":"img/U8/walk/p025_22_03.jpg","say":"항공사진: 호숫가 큰길 옆에 짙은 색 고층 두 동이에요."},{"b":[0.507,0.37,0.483,0.435],"c":[0.4687,0.3483,0.5313,0.4785],"r":1.4805,"img":"img/U8/walk/p025_22_04.jpg","say":"책 그림: 두 동의 평면이에요. 아래에 책 캡션(1950-1951년)이 있어요."},{"b":[0.042,0.902,0.51,0.033],"c":[0.0165,0.8618,0.561,0.1133],"r":6.6019,"img":"img/U8/walk/p025_22_05.jpg","say":"캡션: 미스 반 데어 로에, 레이크쇼어 드라이브 아파트, 미국 시카고, 1951."}]}},{"p":26,"title":"베를린 신 국립미술관(new national gallery), 1968","terms":["new national gallery","테라스 베이스","Ludwig Mies van der Rohe","Barcelona Pavilion","스틸 기둥"],"pass1":[{"kind":"analogy","head":"기둥 여덟 개가 든 철판 쟁반","scene":"커다란 철판 쟁반을 바깥 모서리 쪽 기둥 8개가 들어 올렸다고 생각해 보세요.","map":[["커다란 철판 쟁반","강철 지붕"],["쟁반을 든 기둥 8개","바깥쪽 모서리의 8개 기둥"],["쟁반 밑에 물러 세운 유리 칸막이","지붕선보다 후퇴된 전면 유리벽"]]},{"kind":"say","lines":["**베를린 신 국립미술관(new national gallery)**, 독일 베를린, 1968년이에요.","**미스 반 데어 로에(Ludwig Mies van der Rohe)** 의 8단원 마지막 건물이에요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**테라스 베이스**: 폭이 넓고 바닥을 높인 받침이에요. 건물이 그 위에 올라앉아요.","후퇴: 뒤로 물러남이에요. 유리벽이 지붕 끝보다 안쪽에 서 있다는 뜻이에요.","일시적인 전시: 잠깐 열렸다가 바뀌는 전시예요."]},{"kind":"points","head":"슬라이드 글 세 줄","items":["1. 폭이 넓고 바닥을 높인 **테라스 베이스** 가 갤러리와 사무실들, 레스토랑을 둘러싸고 있음.","2. 강철 지붕은 바깥쪽 모서리에서 8개의 기둥들에 의해 지지.","3. 지붕선보다 후퇴된 전면 유리벽들이 방해받는 것이 없는 개방된 공간을 둘러싸요.","그래서 일시적인 전시를 위해 필요한 대로 배열할 수 있어요."]},{"kind":"points","head":"사진에서 보이는 것","items":["두 사진 모두 넓고 검은 지붕이 유리벽보다 훨씬 바깥까지 나와 있어요.","오른쪽 사진: 지붕 끝 가까이에 검은 기둥이 서 있어요. 유리벽은 그 안쪽에 있어요.","왼쪽 사진의 분홍 현수막에는 'Das MoMA in Berlin' 이라고 적혀 있어요. 슬라이드 설명은 없어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**베를린 신 국립미술관(new national gallery)** 의 강철 지붕을 지지하는 것은 무엇일까요?","choices":["바깥쪽 모서리에서 8개의 기둥","두 개의 양단 트레버틴 벽체","가운데의 **하나의 섬(island)**"],"a":0,"why":"강철 지붕은 바깥쪽 모서리에서 8개의 기둥들에 의해 지지돼요."},{"kind":"warn","head":"숫자 8이 두 번","items":["**바르셀로나 박람회 독일관(Barcelona Pavilion)**(1929): 평평한 슬라브 지붕을 여덟 개의 **스틸 기둥** 이 지지.","**베를린 신 국립미술관(new national gallery)**(1968): 강철 지붕을 바깥쪽 모서리에서 8개의 기둥이 지지.","둘 다 8이에요. 신 국립미술관은 '바깥쪽 모서리' 라는 위치가 붙어요."]},{"kind":"english","head":"논술 답안: 베를린 신 국립미술관","en":"베를린 신 국립미술관(1968)은 강철 지붕을 바깥쪽 모서리의 8개 기둥이 지지하고, 지붕선보다 후퇴된 전면 유리벽이 개방된 공간을 둘러싸 일시적인 전시를 필요한 대로 배열할 수 있으며, 테라스 베이스가 갤러리와 사무실들, 레스토랑을 둘러싼다.","ko":"지붕과 8개 기둥 → 후퇴된 유리벽(개방된 공간) → 테라스 베이스 순서예요.","tip":"'육팔(68)년, 기둥은 팔(8)개' 로 외워요."}],"walk":{"head":{"b":[0.059,0.0541,0.4182,0.0511],"c":[0.0381,0.0381,0.46,0.0831],"r":7.3807,"img":"img/U8/walk/p026_h.jpg"},"parts":[{"b":[0.066,0.177,0.89,0.045],"c":[0.021,0.1006,0.979,0.1978],"r":6.5993,"img":"img/U8/walk/p026_23_01.jpg","say":"1. 테라스 베이스가 갤러리, 사무실들, 레스토랑을 둘러싸요."},{"b":[0.066,0.235,0.62,0.045],"c":[0.035,0.1886,0.682,0.1378],"r":6.5989,"img":"img/U8/walk/p026_23_02.jpg","say":"2. 강철 지붕은 바깥쪽 모서리에서 8개의 기둥이 지지."},{"b":[0.066,0.297,0.91,0.095],"c":[0,0.2434,1,0.2022],"r":6.5941,"img":"img/U8/walk/p026_23_03.jpg","say":"3. 지붕선보다 후퇴된 전면 유리벽, 일시적인 전시를 위한 개방된 공간."},{"b":[0.019,0.457,0.474,0.473],"c":[0,0.4334,0.5214,0.5203],"r":1.3362,"img":"img/U8/walk/p026_23_04.jpg","say":"왼쪽 사진: 넓은 검은 지붕 아래 유리 홀이에요."},{"b":[0.522,0.457,0.473,0.473],"c":[0.4797,0.4334,0.5203,0.5203],"r":1.3333,"img":"img/U8/walk/p026_23_05.jpg","say":"오른쪽 사진: 지붕 끝 가까이의 기둥, 그 안쪽의 유리벽이에요."},{"b":[0.277,0.945,0.405,0.032],"c":[0.2568,0.89,0.4455,0.11],"r":5.4,"img":"img/U8/walk/p026_23_06.jpg","say":"캡션: 미스 반 데어 로에, 신 국립미술관, 독일 베를린, 1968."}]}},{"p":27,"title":"신 국립미술관 모형, 진입층과 지하층 평면","terms":["new national gallery","테라스 베이스"],"pass1":[{"kind":"say","lines":["**베를린 신 국립미술관(new national gallery)** 의 모형 사진과 도면 두 장이에요.","도면 이름은 진입층과 지하층이에요.","유리 홀은 위에 있고, 넓은 받침 안쪽에 또 한 층이 있어요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["진입층: 사람이 들어가는 입구가 있는 층이에요.","지하층: 땅 아래 층이에요.","**테라스 베이스**: 폭이 넓고 바닥을 높인 받침이에요(26쪽)."]},{"kind":"points","head":"모형과 도면에서 보이는 것","items":["모형: 넓은 지붕 아래 유리 홀이 있고, 앞에 넓은 **테라스 베이스** 가 펼쳐져 있어요.","받침 위에는 조각 작품들과 사람 모형이 놓여 있고, 왼쪽 아래로 계단이 내려가요.","받침 옆면에도 유리창이 길게 나 있어요. 그 안쪽이 아래층이에요.","진입층 도면: 가운데 정사각형 홀 안에 칸막이가 거의 없어요.","지하층 도면: 방이 여러 개로 나뉘어 있어요.","26쪽 글처럼 테라스 베이스가 갤러리와 사무실들, 레스토랑을 둘러싸는 구성이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"27쪽 도면 두 장의 이름 짝으로 옳은 것은 무엇일까요?","choices":["진입층, 지하층","1층, 2층","**천정도**, 단면도"],"a":0,"why":"위가 진입층, 아래가 지하층이에요. 천정도는 30쪽에 나와요."}],"walk":{"head":null,"parts":[{"b":[0.012,0.236,0.522,0.555],"c":[0,0.2083,0.5742,0.6105],"r":1.2541,"img":"img/U8/walk/p027_22_01.jpg","say":"모형: 지붕 아래 유리 홀, 앞에 넓은 테라스 베이스와 조각들이에요."},{"b":[0.46,0.04,0.06,0.035],"c":[0.39,0.0025,0.2,0.11],"r":2.4242,"img":"img/U8/walk/p027_22_02.jpg","say":"도면 이름: 진입층."},{"b":[0.555,0.03,0.405,0.455],"c":[0.5348,0.0072,0.4455,0.5005],"r":1.1868,"img":"img/U8/walk/p027_22_03.jpg","say":"진입층 도면: 가운데 정사각형 홀에 칸막이가 거의 없어요."},{"b":[0.46,0.955,0.06,0.035],"c":[0.39,0.89,0.2,0.11],"r":2.4242,"img":"img/U8/walk/p027_22_04.jpg","say":"도면 이름: 지하층."},{"b":[0.548,0.533,0.423,0.457],"c":[0.5269,0.4973,0.4653,0.5027],"r":1.2341,"img":"img/U8/walk/p027_22_05.jpg","say":"지하층 도면: 방이 여러 개로 나뉘어 있어요."}]}},{"p":28,"title":"이성의 오아시스: 혼란 속에 질서를","terms":["이성의 오아시스","new national gallery","Ludwig Mies van der Rohe"],"pass1":[{"kind":"analogy","head":"시끄러운 시장 한가운데 조용한 방","scene":"시끌벅적한 시장 한복판에 반듯하고 조용한 방이 하나 있으면 숨이 놓이죠.","map":[["시끌벅적한 시장","대도시의 혼란한 상태"],["반듯하고 조용한 방","**이성의 오아시스**"],["방을 반듯하게 정리하기","혼란 속에 질서를 세우기"]]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["이성: 차분하게 따지고 생각하는 힘이에요.","오아시스: 사막 한가운데 물과 나무가 있는 쉼터예요.","**이성의 오아시스**: 대도시의 혼란 속에 넣은 차분한 쉼터라는 뜻이에요."]},{"kind":"points","head":"슬라이드 글","items":["**베를린 신 국립미술관(new national gallery)** 을 대도시의 혼란한 상태 속에 **이성의 오아시스** 로 넣고자 함.","함께 실린 말: \"예술의 과제는 현시대의 절망적인 혼란 속에 질서를 세우는 것\"."]},{"kind":"points","head":"사진에서 보이는 것","items":["위 사진: 넓은 지붕 아래 사방이 유리인 홀이에요. 지붕 끝 가까이에 기둥이 서 있어요.","왼쪽 아래: 지붕 끝 아래 검은 기둥과 유리벽이에요. 지붕이 기둥보다 더 나와 있어요.","오른쪽 아래: 지붕 밑을 올려다본 모습이에요. 철 보가 바둑판 격자를 이뤄요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"빈칸에 들어갈 말은? \"예술의 과제는 현시대의 절망적인 혼란 속에 ( )를 세우는 것\"","choices":["질서","장식","기념비"],"a":0,"why":"질서예요. 혼란 속에 질서, 그래서 이성의 오아시스예요."},{"kind":"warn","head":"이 쪽에서 조심할 점","items":["슬라이드에는 따옴표 속 말을 누가 했는지 적혀 있지 않아요.","답안에는 '~라는 말과 함께 소개된다' 처럼 슬라이드 모양 그대로 써요."]},{"kind":"english","head":"논술 답안: 이성의 오아시스","en":"미스는 베를린 신 국립미술관을 대도시의 혼란한 상태 속에 이성의 오아시스로 넣고자 하였으며, 이 건물은 '예술의 과제는 현시대의 절망적인 혼란 속에 질서를 세우는 것' 이라는 말과 함께 소개된다.","ko":"혼란한 대도시 → 이성의 오아시스 → 혼란 속에 질서 순서예요.","tip":"'혼란 속 오아시스, 혼란 속 질서' 로 짝지어 외워요."}],"walk":{"head":null,"parts":[{"b":[0.045,0.155,0.355,0.1],"c":[0.0272,0.139,0.3905,0.132],"r":3.9444,"img":"img/U8/walk/p028_23_01.jpg","say":"대도시의 혼란한 상태 속에 이성의 오아시스로 넣고자 함."},{"b":[0.045,0.325,0.36,0.1],"c":[0.027,0.309,0.396,0.132],"r":4.0,"img":"img/U8/walk/p028_23_02.jpg","say":"예술의 과제는 현시대의 절망적인 혼란 속에 질서를 세우는 것."},{"b":[0.432,0.045,0.518,0.445],"c":[0.4061,0.0228,0.5698,0.4895],"r":1.5521,"img":"img/U8/walk/p028_23_03.jpg","say":"위 사진: 넓은 지붕 아래 사방이 유리인 홀이에요."},{"b":[0.042,0.542,0.457,0.452],"c":[0.0192,0.5028,0.5027,0.4972],"r":1.3481,"img":"img/U8/walk/p028_23_04.jpg","say":"왼쪽 아래: 지붕 끝 아래 검은 기둥과 유리벽이에요."},{"b":[0.507,0.537,0.45,0.455],"c":[0.4845,0.4995,0.495,0.5005],"r":1.3187,"img":"img/U8/walk/p028_23_05.jpg","say":"오른쪽 아래: 지붕 밑의 바둑판 격자예요."}]}},{"p":29,"title":"10년간 복원공사 후 2021년 재개관, 2005년 퍼포먼스","terms":["new national gallery"],"pass1":[{"kind":"say","lines":["사진 두 장과 짧은 글 두 줄이에요.","위: 10년간 복원공사 후 2021년 재개관. 아래: 2005년 퍼포먼스.","오래된 **베를린 신 국립미술관(new national gallery)** 을 오래 고쳐서 다시 열었다는 이야기예요."]}],"pass2":[{"kind":"points","head":"사진에서 보이는 것","items":["위 사진: 길 건너에서 본 정면이에요. 넓은 지붕 아래 유리벽과 큰 글자 판이 보여요.","아래 사진: 홀 안이에요. 격자 천장 아래 많은 사람이 줄지어 서 있어요.","홀 양옆에 짙은 무늬 돌로 싼 큰 덩어리 두 개가 서 있어요.","유리벽 너머 바깥이 그대로 보여요. 홀 안에 칸막이가 없어요."]},{"kind":"points","head":"연도 정리","items":["1968: 캡션의 연도예요(26쪽).","2005: 퍼포먼스 사진의 해예요.","10년간 복원공사, 그 뒤 2021년 재개관이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**베를린 신 국립미술관(new national gallery)** 의 재개관 연도는 언제일까요?","choices":["2005년","2021년","1986년"],"a":1,"why":"10년간 복원공사 후 2021년 재개관이에요. 2005년은 퍼포먼스, 1986년은 바르셀로나 독일관 복원이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["복원공사를 시작한 해는 슬라이드에 없어요. 2021에서 10을 빼서 만들지 않아요.","복원 두 개: 바르셀로나 독일관 1986 복원, 신 국립미술관 2021 재개관."]}],"walk":{"head":null,"parts":[{"b":[0.112,0.025,0.83,0.41],"c":[0.0705,0.0045,0.913,0.451],"r":2.6992,"img":"img/U8/walk/p029_22_01.jpg","say":"위 사진: 길 건너에서 본 정면이에요."},{"b":[0.045,0.452,0.27,0.033],"c":[0.0315,0.4135,0.297,0.11],"r":3.6,"img":"img/U8/walk/p029_22_02.jpg","say":"글: 10년간 복원공사 후 2021년 재개관."},{"b":[0.35,0.453,0.6,0.53],"c":[0.32,0.417,0.66,0.583],"r":1.5094,"img":"img/U8/walk/p029_22_03.jpg","say":"아래 사진: 격자 천장 아래 홀 안에 사람들이 줄지어 서 있어요."},{"b":[0.155,0.953,0.13,0.03],"c":[0.12,0.89,0.2,0.11],"r":2.4242,"img":"img/U8/walk/p029_22_04.jpg","say":"글: 2005년 퍼포먼스."}]}},{"p":30,"title":"전시 실내와 천정도","terms":["천정도","new national gallery","스틸 기둥"],"pass1":[{"kind":"say","lines":["왼쪽은 빨간 전시 벽이 선 실내 사진, 오른쪽은 **천정도** 예요.","**천정도** 는 천장을 올려다본 모양을 그린 도면이에요.","작은 네모가 바둑판처럼 빽빽하게 이어져요."]}],"pass2":[{"kind":"points","head":"보이는 것","items":["이 쪽에는 건물 이름이 따로 없어요. 26-29쪽 **베를린 신 국립미술관(new national gallery)** 다음에 나와요.","왼쪽 사진: 검은 격자 천장 아래 빨간 전시 벽들이 세워져 있어요.","26쪽 글처럼 일시적인 전시를 위해 필요한 대로 벽을 세운 모습으로 보여요.","오른쪽 **천정도**: 큰 정사각형 격자 안에 더 진한 정사각형 격자가 있어요.","가장자리에 작은 표시가 위, 아래, 왼쪽, 오른쪽에 두 개씩, 모두 여덟 개 있어요.","26쪽 '8개의 기둥' 과 숫자가 같아요. 다만 슬라이드가 이것을 기둥이라고 적지는 않았어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"warn","head":"표기 조심","items":["19쪽 글은 '천장', 이 쪽 도면 이름은 '**천정도**' 예요. 같은 천장을 가리켜요.","슬라이드 표기 그대로 '**천정도**' 로 외워요.","바르셀로나의 여덟 개 **스틸 기둥** 처럼, 8이라는 숫자는 26쪽 글로 확인해요."]}],"walk":{"head":null,"parts":[{"b":[0.01,0.115,0.435,0.77],"c":[0,0.0765,0.4785,0.847],"r":0.7532,"img":"img/U8/walk/p030_21_01.jpg","say":"왼쪽 사진: 검은 격자 천장 아래 빨간 전시 벽들이에요."},{"b":[0.458,0.145,0.517,0.708],"c":[0.4313,0.1096,0.5687,0.7788],"r":0.9736,"img":"img/U8/walk/p030_21_02.jpg","say":"천정도: 큰 격자 안에 더 진한 정사각형 격자가 있어요."},{"b":[0.59,0.145,0.25,0.03],"c":[0.5775,0.105,0.275,0.11],"r":3.3333,"img":"img/U8/walk/p030_21_03.jpg","say":"위쪽 가장자리의 작은 표시 두 개예요. 네 변에 두 개씩 있어요."},{"b":[0.868,0.912,0.055,0.033],"c":[0.7955,0.8735,0.2,0.11],"r":2.4242,"img":"img/U8/walk/p030_21_04.jpg","say":"도면 이름: 천정도."}]}},{"p":31,"title":"캡션 없는 실내 투시 콜라주 두 장 (8단원 마지막)","terms":["Ludwig Mies van der Rohe","Less is more","벽체","Barcelona Pavilion","Tugendhat Villa","Farnsworth house","new national gallery","Functionalism"],"pass1":[{"kind":"say","lines":["8단원 마지막 쪽이에요. 캡션이 하나도 없는 그림 두 장이에요.","선으로 그린 실내에 그림과 조각상 사진을 오려 붙인 콜라주예요.","기둥 몇 개, 벽 판 몇 장, 그림과 조각상. 그게 전부예요."]},{"kind":"recap","items":["8단원 한 줄 정리","**미스 반 데어 로에(Ludwig Mies van der Rohe)**, 독일의 대표적 **기능주의(Functionalism)** 건축가예요.","**적을수록 많다(Less is more)**: 벽은 떼어 세우고, 지붕은 기둥이 들고, 장식 대신 재료의 무늬.","1929 바르셀로나 → 1930 투겐다트 → 1950 판스워스 → 1968 신 국립미술관."]}],"pass2":[{"kind":"points","head":"그림에서 보이는 것","items":["위 그림: 가는 기둥 셋, 검은 벽 판, 추상화 한 점, 서 있는 조각상, 격자 바닥이에요.","아래 그림: 바깥 숲이 보이는 유리벽, 낮은 흰 벽, 나무 무늬 낮은 벽이 있어요.","아래 그림에는 둥근 무늬 그림, 서 있는 조각상, 바닥에 누운 조각상도 있어요.","작품 이름과 연도가 없어서 어느 건물 그림인지 이 쪽만으로는 몰라요."]},{"kind":"points","head":"앞에서 배운 것과 닮은 점","items":["가는 기둥 몇 개만 서 있고, 벽은 홀로 선 판처럼 놓였어요.","브릭 빌라에서 본 '독립해서 서 있는 건축요소' 로서의 **벽체** 와 닮았어요.","넓게 트인 공간에 그림과 조각상만 놓였어요. **적을수록 많다(Less is more)** 의 느낌이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"warn","head":"지어내지 않기","items":["이 쪽의 작품 이름, 화가, 조각가는 슬라이드에 없어요.","12쪽 바르셀로나의 '게오르그 콜베의 조각상' 과 섞지 않아요. 여기에는 이름이 없어요."]},{"kind":"check","q":"8단원 작품과 연도 짝으로 틀린 것은 무엇일까요?","choices":["**바르셀로나 박람회 독일관(Barcelona Pavilion)**, 1929","**투겐다트 주택(Tugendhat Villa)**, 1930","**판스워스 하우스(Farnsworth house)**, 1955"],"a":2,"why":"판스워스 하우스는 1950이에요. 1955는 크라운 홀이에요."},{"kind":"english","head":"논술 답안: 미스 반 데어 로에의 전후 작품","en":"미스 반 데어 로에는 전후 모더니즘 시기에 판스워스 하우스(1950), 레이크쇼어 드라이브 아파트(1951), 크라운 홀(1955), 베를린 신 국립미술관(1968)을 설계하였다.","ko":"연도 순서 50 → 51 → 55 → 68이에요.","tip":"'오공(50)은 사방이 유리, 육팔(68)은 기둥이 팔(8)개' 로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.165,0.025,0.67,0.47],"c":[0.1315,0.0015,0.737,0.517],"r":1.9007,"img":"img/U8/walk/p031_22_01.jpg","say":"위 그림: 가는 기둥, 검은 벽 판, 추상화, 조각상, 격자 바닥이에요."},{"b":[0.397,0.133,0.17,0.2],"c":[0.382,0.117,0.2,0.232],"r":1.1494,"img":"img/U8/walk/p031_22_02.jpg","say":"위 그림 가운데: 오려 붙인 추상화 한 점이에요."},{"b":[0.687,0.2,0.06,0.25],"c":[0.617,0.184,0.2,0.282],"r":0.9456,"img":"img/U8/walk/p031_22_03.jpg","say":"위 그림 오른쪽: 서 있는 조각상이에요."},{"b":[0.09,0.528,0.82,0.46],"c":[0.049,0.494,0.902,0.506],"r":2.3768,"img":"img/U8/walk/p031_22_04.jpg","say":"아래 그림: 유리벽 너머 숲, 낮은 벽, 그림, 조각상이에요."},{"b":[0.095,0.712,0.19,0.235],"c":[0.083,0.696,0.214,0.267],"r":1.0687,"img":"img/U8/walk/p031_22_05.jpg","say":"아래 그림 왼쪽: 둥근 무늬가 있는 그림이에요."}]}}]};
